{"command":"mkdir -p /workspace/cmd/cheat && cat > /workspace/cmd/cheat/flags.go <<'EOF'
package main

import (
	"fmt"
	"sort"
	"strconv"
	"strings"
)

// flag describes a single command-line option.
type flag struct {
	Name    string
	Short   string
	IsBool  bool
	Usage   string
	Value   string
	Changed bool
}

// flagSet is a small POSIX/GNU style option parser.
type flagSet struct {
	flags  map[string]*flag
	shorts map[byte]*flag
	args   []string
	dash   int
}

func newFlagSet() *flagSet {
	return &flagSet{flags: map[string]*flag{}, shorts: map[byte]*flag{}, dash: -1}
}

func (fs *flagSet) add(name, short string, isBool bool, usage string) {
	f := &flag{Name: name, Short: short, IsBool: isBool, Usage: usage}
	if isBool {
		f.Value = "false"
	}
	fs.flags[name] = f
	if short != "" {
		fs.shorts[short[0]] = f
	}
}

// sorted returns all flags ordered by name.
func (fs *flagSet) sorted() []*flag {
	names := make([]string, 0, len(fs.flags))
	for n := range fs.flags {
		names = append(names, n)
	}
	sort.Strings(names)
	out := make([]*flag, 0, len(names))
	for _, n := range names {
		out = append(out, fs.flags[n])
	}
	return out
}

func (fs *flagSet) lookup(name string) *flag { return fs.flags[name] }

func (fs *flagSet) bool(name string) bool {
	f := fs.flags[name]
	if f == nil {
		return false
	}
	b, _ := strconv.ParseBool(f.Value)
	return b
}

func (fs *flagSet) str(name string) string {
	if f := fs.flags[name]; f != nil {
		return f.Value
	}
	return ""
}

func (fs *flagSet) changed(name string) bool {
	if f := fs.flags[name]; f != nil {
		return f.Changed
	}
	return false
}

func (fs *flagSet) set(f *flag, value string) error {
	if f.IsBool {
		if _, err := strconv.ParseBool(value); err != nil {
			var fname string
			if f.Short != "" {
				fname = fmt.Sprintf("-%s, --%s", f.Short, f.Name)
			} else {
				fname = fmt.Sprintf("--%s", f.Name)
			}
			return fmt.Errorf("invalid argument %q for %q flag: %v", value, fname, err)
		}
	}
	f.Value = value
	f.Changed = true
	return nil
}

// parse parses the arguments; positional arguments are accumulated.
func (fs *flagSet) parse(arguments []string) error {
	fs.args = make([]string, 0, len(arguments))
	fs.dash = -1
	args := arguments
	for len(args) > 0 {
		s := args[0]
		args = args[1:]
		if len(s) == 0 || s[0] != '-' || len(s) == 1 {
			fs.args = append(fs.args, s)
			continue
		}
		var err error
		if s[1] == '-' {
			if len(s) == 2 {
				fs.dash = len(fs.args)
				fs.args = append(fs.args, args...)
				break
			}
			args, err = fs.parseLong(s, args)
		} else {
			args, err = fs.parseShort(s, args)
		}
		if err != nil {
			return err
		}
	}
	return nil
}

func (fs *flagSet) parseLong(s string, args []string) ([]string, error) {
	a := args
	name := s[2:]
	if len(name) == 0 || name[0] == '-' || name[0] == '=' {
		return a, fmt.Errorf("bad flag syntax: %s", s)
	}
	split := strings.SplitN(name, "=", 2)
	name = split[0]
	f, ok := fs.flags[name]
	if !ok {
		return a, fmt.Errorf("unknown flag: --%s", name)
	}
	var value string
	if len(split) == 2 {
		value = split[1]
	} else if f.IsBool {
		value = "true"
	} else if len(a) > 0 {
		value = a[0]
		a = a[1:]
	} else {
		return a, fmt.Errorf("flag needs an argument: %s", s)
	}
	return a, fs.set(f, value)
}

func (fs *flagSet) parseSingleShort(shorthands string, args []string) (string, []string, error) {
	outArgs := args
	outShorts := shorthands[1:]
	c := shorthands[0]
	f, ok := fs.shorts[c]
	if !ok {
		return outShorts, outArgs, fmt.Errorf("unknown shorthand flag: %q in -%s", c, shorthands)
	}
	var value string
	if len(shorthands) > 2 && shorthands[1] == '=' {
		value = shorthands[2:]
		outShorts = ""
	} else if f.IsBool {
		value = "true"
	} else if len(shorthands) > 1 {
		value = shorthands[1:]
		outShorts = ""
	} else if len(args) > 0 {
		value = args[0]
		outArgs = args[1:]
	} else {
		return outShorts, outArgs, fmt.Errorf("flag needs an argument: %q in -%s", c, shorthands)
	}
	return outShorts, outArgs, fs.set(f, value)
}

func (fs *flagSet) parseShort(s string, args []string) ([]string, error) {
	a := args
	shorthands := s[1:]
	var err error
	for len(shorthands) > 0 {
		shorthands, a, err = fs.parseSingleShort(shorthands, args)
		if err != nil {
			return a, err
		}
	}
	return a, nil
}

// newCheatFlags builds the flag set used by cheat.
func newCheatFlags() *flagSet {
	fs := newFlagSet()
	fs.add("all", "a", true, "Search among all cheatpaths")
	fs.add("brief", "b", true, "List cheatsheets without file paths")
	fs.add("colorize", "c", true, "Colorize output")
	fs.add("completion", "", false, "Generate shell completion script (`shell`: bash, zsh, fish, powershell)")
	fs.add("conf", "", true, "Display the config file path")
	fs.add("directories", "d", true, "List cheatsheet directories")
	fs.add("edit", "e", false, "Edit `cheatsheet`")
	fs.add("init", "", true, "Write a default config file to stdout")
	fs.add("list", "l", true, "List cheatsheets")
	fs.add("path", "p", false, "Return only sheets found on cheatpath `name`")
	fs.add("regex", "r", true, "Treat search <phrase> as a regex")
	fs.add("rm", "", false, "Remove (delete) `cheatsheet`")
	fs.add("search", "s", false, "Search cheatsheets for `phrase`")
	fs.add("tag", "t", false, "Return only sheets matching `tag`")
	fs.add("tags", "T", true, "List all tags in use")
	fs.add("update", "u", true, "Update git-backed cheatpaths")
	fs.add("version", "v", true, "Print the version number")
	fs.add("help", "h", true, "help for cheat")
	return fs
}
EOF"}

