	paths = append(paths,
		filepath.Join(home, ".config", "cheat", "conf.yml"),
		filepath.Join(home, ".cheat", "conf.yml"),
		"/etc/cheat/conf.yml",
	)
	return paths, nil
}

// findEditor locates an editor appropriate for the environment.
func findEditor() (string, error) {
	if v := os.Getenv("VISUAL"); v != "" {
		return v, nil
	}
	if v := os.Getenv("EDITOR"); v != "" {
		return v, nil
	}
	for _, e := range []string{"editor", "nano", "vim"} {
		if p, err := exec.LookPath(e); err == nil {
			return p, nil
		}
	}
	return "", fmt.Errorf("no editor set")
}

// findPager locates a pager appropriate for the environment.
func findPager() string {
	if v := os.Getenv("PAGER"); v != "" {
		return v
	}
	for _, p := range []string{"pager", "less", "more"} {
		if path, err := exec.LookPath(p); err == nil {
			return path
		}
	}
	return ""
}

// loadConfig reads and processes the config file at confPath.
func loadConfig(confPath string) (Config, error) {
	buf, err := os.ReadFile(confPath)
	if err != nil {
		return Config{}, fmt.Errorf("could not read config file: %v", err)
	}
	conf, err := decodeConfig(buf)
	if err != nil {
		return Config{}, fmt.Errorf("could not unmarshal yaml: %v", err)
	}
	conf.Path = confPath

	// a .cheat directory in the cwd or any ancestor is appended
	if cwd, err := os.Getwd(); err == nil {
		dir := cwd
		for {
			local := filepath.Join(dir, ".cheat")
			if fi, err := os.Stat(local); err == nil && fi.IsDir() {
				conf.Cheatpaths = append(conf.Cheatpaths, Cheatpath{
					Name:     "cwd",
					Path:     local,
					ReadOnly: false,
					Tags:     []string{},
				})
				break
			}
			parent := filepath.Dir(dir)
			if parent == dir {
				break
			}
			dir = parent
		}
	}

	valid := []Cheatpath{}
	for _, cp := range conf.Cheatpaths {
		expanded, err := expandHome(cp.Path)
		if err != nil {
			return Config{}, fmt.Errorf("failed to expand ~: %v", err)
		}
		evaled, err := filepath.EvalSymlinks(expanded)
		if err != nil {
			if os.IsNotExist(err) {
				fmt.Fprintf(os.Stderr, "WARNING: cheatpath '%s' does not exist, skipping\n", expanded)
				continue
			}
			return Config{}, fmt.Errorf("failed to resolve symlink: %s: %v", expanded, err)
		}
		cp.Path = evaled
		valid = append(valid, cp)
	}
	conf.Cheatpaths = valid

	if v := os.Getenv("VISUAL"); v != "" {
		conf.Editor = v
	} else if v := os.Getenv("EDITOR"); v != "" {
		conf.Editor = v
	}
	if conf.Editor == "" {
		ed, err := findEditor()
		if err != nil {
			return Config{}, err
		}
		conf.Editor = ed
	}
	if conf.Style == "" {
		conf.Style = "bw"
	}
	if conf.Formatter == "" {
		conf.Formatter = "terminal"
	}
	conf.Pager = strings.TrimSpace(conf.Pager)
	return conf, nil
}

// validate asserts that the config is usable.
func (c *Config) validate() error {
	if len(c.Cheatpaths) == 0 {
		return fmt.Errorf("config error: no cheatpaths specified")
	}
	names := map[string]bool{}
	paths := map[string]bool{}
	for _, cp := range c.Cheatpaths {
		if cp.Name == "" {
			return fmt.Errorf("config error: cheatpath name cannot be empty")
		}
		if names[cp.Name] {
			return fmt.Errorf("config error: cheatpath name is not unique: %s", cp.Name)
		}
		names[cp.Name] = true
		if paths[cp.Path] {
			return fmt.Errorf("config error: cheatpath path is not unique: %s", cp.Path)
		}
		paths[cp.Path] = true
	}
	switch c.Formatter {
	case "terminal", "terminal256", "terminal16m":
	default:
		return fmt.Errorf("config error: formatter is invalid: %s", c.Formatter)
	}
	return nil
}

// colorize reports whether output should be colorized.
func (c *Config) colorize(force bool) bool {
	if force {
		return true
	}
	if c.Colorize {
		return isTerminal(os.Stdout)
	}
	return false
}

// filterCheatpaths returns only the cheatpath named name.
func filterCheatpaths(paths []Cheatpath, name string) ([]Cheatpath, error) {
	for _, p := range paths {
		if p.Name == name {
			return []Cheatpath{p}, nil
		}
	}
	return nil, fmt.Errorf("cheatpath does not exist: %s", name)
}

// writeablePath returns the most local writeable cheatpath.
func writeablePath(paths []Cheatpath) (Cheatpath, error) {
	for i := len(paths) - 1; i >= 0; i-- {
		if !paths[i].ReadOnly {
			return paths[i], nil
		}
	}
	return Cheatpath{}, fmt.Errorf("no writeable cheatpaths found")
}
EOF

