package main

import (
	"fmt"
	"io"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strings"
)

// Sheet is a single cheatsheet.
type Sheet struct {
	Title     string
	CheatPath string
	Path      string
	Text      string
	Tags      []string
	Syntax    string
	ReadOnly  bool
}

// Frontmatter holds the parsed sheet header.
type Frontmatter struct {
	Syntax string
	Tags   []string
}

// parseFrontmatter splits markdown into text and frontmatter.
func parseFrontmatter(markdown string) (string, Frontmatter, error) {
	linebreak := "\n"
	if strings.Contains(markdown, "\r\n") {
		linebreak = "\r\n"
	}
	delim := "---" + linebreak
	var fm Frontmatter
	if !strings.HasPrefix(markdown, delim) {
		return markdown, fm, nil
	}
	parts := strings.SplitN(markdown, delim, 3)
	if len(parts) != 3 {
		return markdown, fm, fmt.Errorf("failed to delimit frontmatter")
	}
	fm, err := decodeFrontmatter([]byte(parts[1]))
	if err != nil {
		return parts[2], fm, fmt.Errorf("failed to unmarshal frontmatter: %v", err)
	}
	return parts[2], fm, nil
}

// newSheet loads a sheet from disk.
func newSheet(title, cheatpath, path string, tags []string, readOnly bool) (Sheet, error) {
	buf, err := os.ReadFile(path)
	if err != nil {
		return Sheet{}, fmt.Errorf("failed to read file: %s, %v", path, err)
	}
	text, fm, err := parseFrontmatter(string(buf))
	if err != nil {
		return Sheet{}, fmt.Errorf("failed to parse front-matter: %v", err)
	}
	all := make([]string, 0, len(tags)+len(fm.Tags))
	all = append(all, tags...)
	all = append(all, fm.Tags...)
	sort.Strings(all)
	return Sheet{
		Title:     title,
		CheatPath: cheatpath,
		Path:      path,
		Text:      text,
		Tags:      all,
		Syntax:    fm.Syntax,
		ReadOnly:  readOnly,
	}, nil
}

// tagged reports whether the sheet carries tag.
func (s *Sheet) tagged(tag string) bool {
	for _, t := range s.Tags {
		if t == tag {
			return true
		}
	}
	return false
}

// search returns the paragraphs of the sheet matching reg.
func (s *Sheet) search(reg *regexp.Regexp) string {
	matches := []string{}
	for _, chunk := range strings.Split(s.Text, "\n\n") {
		if reg.MatchString(chunk) {
			matches = append(matches, chunk)
		}
	}
	return strings.Join(matches, "\n\n")
}

// copyTo copies the raw sheet file to dest.
func (s *Sheet) copyTo(dest string) error {
	infile, err := os.Open(s.Path)
	if err != nil {
		return fmt.Errorf("failed to open cheatsheet: %s, %v", s.Path, err)
	}
	defer infile.Close()
	dirs := filepath.Dir(dest)
	if dirs != "." {
		if err := os.MkdirAll(dirs, 0755); err != nil {
			return fmt.Errorf("failed to create directory: %s, %v", dirs, err)
		}
	}
	outfile, err := os.Create(dest)
	if err != nil {
		return fmt.Errorf("failed to create outfile: %s, %v", dest, err)
	}
	defer outfile.Close()
	if _, err := io.Copy(outfile, infile); err != nil {
		return fmt.Errorf("failed to copy file: infile: %s, outfile: %s, err: %v", s.Path, dest, err)
	}
	return nil
}

// isGitDir reports whether a directory should be skipped as git metadata.
func isGitDir(name string) bool {
	return name == ".git"
}

// loadSheets loads all sheets on all cheatpaths.
func loadSheets(cheatpaths []Cheatpath) ([]map[string]Sheet, error) {
	sheets := make([]map[string]Sheet, len(cheatpaths))
	for i, cp := range cheatpaths {
		pathSheets := map[string]Sheet{}
		err := filepath.Walk(cp.Path, func(path string, info os.FileInfo, err error) error {
			if err != nil {
				return fmt.Errorf("failed to walk path: %v", err)
			}
			if info.IsDir() {
				if isGitDir(info.Name()) {
					return filepath.SkipDir
				}
				return nil
			}
			name := info.Name()
			if strings.HasPrefix(name, ".") {
				return nil
			}
			if filepath.Ext(name) != "" {
				return nil
			}
			title := strings.TrimPrefix(strings.TrimPrefix(path, cp.Path), string(os.PathSeparator))
			s, err := newSheet(title, cp.Name, path, cp.Tags, cp.ReadOnly)
			if err != nil {
				return fmt.Errorf("failed to load sheet: %s, path: %s, err: %v", title, path, err)
			}
			pathSheets[title] = s
			return nil
		})
		if err != nil {
			return sheets, fmt.Errorf("failed to load cheatsheets: %v", err)
		}
		sheets[i] = pathSheets
	}
	return sheets, nil
}

// filterSheets keeps only sheets tagged with all of tags.
func filterSheets(cheatpaths []map[string]Sheet, tags []string) []map[string]Sheet {
	filtered := make([]map[string]Sheet, 0, len(cheatpaths))
	for _, cp := range cheatpaths {
		pf := map[string]Sheet{}
		for title, s := range cp {
			keep := true
			for _, tag := range tags {
				if !s.tagged(strings.TrimSpace(tag)) {
					keep = false
					break
				}
			}
			if keep {
				pf[title] = s
			}
		}
		filtered = append(filtered, pf)
	}
	return filtered
}

// consolidateSheets merges cheatpaths, letting later paths override earlier.
func consolidateSheets(cheatpaths []map[string]Sheet) map[string]Sheet {
	out := map[string]Sheet{}
	for _, cp := range cheatpaths {
		for title, s := range cp {
			out[title] = s
		}
	}
	return out
}

// sortedSheets returns the sheets of a path sorted by title.
func sortedSheets(m map[string]Sheet) []Sheet {
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	out := make([]Sheet, 0, len(keys))
	for _, k := range keys {
		out = append(out, m[k])
	}
	return out
}

// allTags returns the sorted unique tags in use.
func allTags(cheatpaths []map[string]Sheet) []string {
	seen := map[string]bool{}
	for _, cp := range cheatpaths {
		for _, s := range cp {
			for _, t := range s.Tags {
				seen[t] = true
			}
		}
	}
	tags := make([]string, 0, len(seen))
	for t := range seen {
		tags = append(tags, t)
	}
	sort.Strings(tags)
	return tags
}

// validateSheetName checks a cheatsheet name used for writing.
func validateSheetName(name string) error {
	if name == "" {
		return fmt.Errorf("cheatsheet name cannot be empty")
	}
	if strings.Contains(name, "..") {
		return fmt.Errorf("cheatsheet name cannot contain '..'")
	}
	if filepath.IsAbs(name) {
		return fmt.Errorf("cheatsheet name cannot be an absolute path")
	}
	if strings.HasPrefix(name, "~") {
		return fmt.Errorf("cheatsheet name cannot start with '~'")
	}
	if strings.HasPrefix(filepath.Base(name), ".") {
		return fmt.Errorf("cheatsheet name cannot start with '.' (hidden files are not supported)")
	}
	return nil
}
EOF"}

