	}
	w.Flush()
	write(out.String(), conf)
}

func cmdList(fs *flagSet, args []string, conf Config) {
	sheets := tagFilter(fs, loadSheetsOrDie(conf))
	flattened := []Sheet{}
	for _, ps := range sheets {
		flattened = append(flattened, sortedSheets(ps)...)
	}
	sort.SliceStable(flattened, func(i, j int) bool {
		return flattened[i].Title < flattened[j].Title
	})
	if len(args) > 0 {
		pattern := "(?i)" + args[0]
		reg, err := regexp.Compile(pattern)
		if err != nil {
			fatalf("failed to compile regexp: %s, %v\n", pattern, err)
		}
		filtered := []Sheet{}
		for _, s := range flattened {
			if reg.MatchString(s.Title) {
				filtered = append(filtered, s)
			}
		}
		flattened = filtered
	}
	if len(flattened) == 0 {
		os.Exit(2)
	}
	var out bytes.Buffer
	w := tabwriter.NewWriter(&out, 0, 0, 1, ' ', 0)
	if fs.bool("brief") {
		fmt.Fprintln(w, "title:\ttags:")
		for _, s := range flattened {
			fmt.Fprintf(w, "%s\t%s\n", s.Title, strings.Join(s.Tags, ","))
		}
	} else {
		fmt.Fprintln(w, "title:\tfile:\ttags:")
		for _, s := range flattened {
			fmt.Fprintf(w, "%s\t%s\t%s\n", s.Title, s.Path, strings.Join(s.Tags, ","))
		}
	}
	w.Flush()
	write(out.String(), conf)
}

func cmdTags(conf Config) {
