	phrase := fs.str("search")
	sheets := tagFilter(fs, loadSheetsOrDie(conf))
	pattern := "(?i)" + phrase
	if fs.bool("regex") {
		pattern = phrase
	}
	reg, err := regexp.Compile(pattern)
	if err != nil {
