// resolveConfigPath locates (or installs) the config file.
func resolveConfigPath() string {
	home, err := homeDir()
	if err != nil {
		fatalf("failed to get user home directory: %v\n", err)
	}
	confpaths, err := configPaths(home)
	if err != nil {
		fatalf("failed to read config paths: %v\n", err)
	}
	for _, p := range confpaths {
		if _, err := os.Stat(p); err == nil {
			return p
		}
	}
	yes, err := prompt("A config file was not found. Would you like to create one now? [Y/n]", true)
	if err != nil {
		fatalf("failed to create config: %v\n", err)
	}
	if !yes {
		os.Exit(0)
	}
	confpath := confpaths[0]
	if err := runInstaller(confpath); err != nil {
		fatalf("failed to run installer: %v\n", err)
	}
	fmt.Printf("Created config file: %s\n", confpath)
	fmt.Println("Please read this file for advanced configuration information.")
	os.Exit(0)
	return ""
}

