package main

import (
	"bytes"
	"errors"
	"fmt"
	"net/http"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"time"
)

var (
	errNotRepo  = errors.New("not a git repository")
	errDirty    = errors.New("dirty worktree")
	errUpToDate = errors.New("already up-to-date")
)

func gitCmd(dir string, args ...string) (string, string, error) {
	cmd := exec.Command("git", append([]string{"-C", dir}, args...)...)
	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr
	cmd.Env = append(os.Environ(), "GIT_TERMINAL_PROMPT=0", "LC_ALL=C")
	err := cmd.Run()
	return strings.TrimSpace(stdout.String()), strings.TrimSpace(stderr.String()), err
}

func remoteRefs(dir string) string {
	out, _, _ := gitCmd(dir, "for-each-ref", "--format=%(refname) %(objectname)", "refs/remotes/origin")
	return out
}

// pullRepo updates the git repository at dir.
func pullRepo(dir string) error {
	fi, err := os.Stat(filepath.Join(dir, ".git"))
	if err != nil || fi == nil {
		return errNotRepo
	}
	if _, err := exec.LookPath("git"); err != nil {
		return errNotRepo
	}
	if _, _, err := gitCmd(dir, "rev-parse", "--git-dir"); err != nil {
		return errNotRepo
	}
	status, _, err := gitCmd(dir, "status", "--porcelain", "--untracked-files=all")
	if err != nil {
		return errNotRepo
	}
	if status != "" {
		return errDirty
	}
	url, _, err := gitCmd(dir, "remote", "get-url", "origin")
	if err != nil {
		return errors.New("remote not found")
	}
	if strings.HasPrefix(url, "http://") || strings.HasPrefix(url, "https://") {
		client := &http.Client{Timeout: 60 * time.Second}
		u := strings.TrimSuffix(url, "/") + "/info/refs?service=git-upload-pack"
		resp, err := client.Get(u)
		if err != nil {
			return err
		}
		resp.Body.Close()
		if resp.StatusCode == 404 || resp.StatusCode == 401 || resp.StatusCode == 403 {
			if resp.StatusCode == 404 {
				return errors.New("repository not found")
			}
			return errors.New("authentication required")
		}
	} else if !strings.Contains(url, "://") && !strings.Contains(url, "@") {
		p := strings.TrimPrefix(url, "file://")
		if _, err := os.Stat(p); err != nil {
			return errors.New("repository not found")
		}
	}
	before := remoteRefs(dir)
	if _, stderr, err := gitCmd(dir, "fetch", "-q", "origin"); err != nil {
		if strings.Contains(stderr, "does not appear to be a git repository") || strings.Contains(stderr, "not found") {
			return errors.New("repository not found")
		}
		return errors.New(stderr)
	}
	after := remoteRefs(dir)
	updated := before != after
	if _, _, err := gitCmd(dir, "fetch", "-q", "origin", "HEAD"); err != nil {
		return errors.New("reference not found")
	}
	ref, _, err := gitCmd(dir, "rev-parse", "FETCH_HEAD")
	if err != nil || ref == "" {
		return errors.New("reference not found")
	}
	head, _, err := gitCmd(dir, "rev-parse", "--verify", "-q", "HEAD")
	if err == nil && head != "" {
		_, _, aheadErr := gitCmd(dir, "merge-base", "--is-ancestor", ref, head)
		headAhead := aheadErr == nil
		if !updated && headAhead {
			return errUpToDate
		}
		_, _, ffErr := gitCmd(dir, "merge-base", "--is-ancestor", head, ref)
		if ffErr != nil {
			return errors.New("non-fast-forward update")
		}
		if head == ref {
			return errUpToDate
		}
	}
	if _, stderr, err := gitCmd(dir, "merge", "-q", "--ff-only", ref); err != nil {
		if _, _, err2 := gitCmd(dir, "reset", "-q", "--hard", ref); err2 != nil {
			return errors.New(stderr)
		}
	}
	return nil
}

func cmdUpdate(conf Config) {
	failed := false
	for _, cp := range conf.Cheatpaths {
		err := pullRepo(cp.Path)
		switch {
		case err == nil || err == errUpToDate:
			fmt.Printf("%s: ok\n", cp.Name)
		case err == errNotRepo:
			fmt.Printf("%s: skipped (not a git repository)\n", cp.Name)
		case err == errDirty:
			fmt.Printf("%s: skipped (dirty worktree)\n", cp.Name)
		default:
			fmt.Fprintf(os.Stderr, "%s: error (%v)\n", cp.Name, err)
			failed = true
		}
	}
	if failed {
		os.Exit(1)
	}
}
EOF"}

