import (
	"fmt"
	"os"
	"sort"
	"strconv"
	"strings"
)

const (
	compError       = 1
	compNoSpace     = 2
	compNoFileComp  = 4
	compFilterExt   = 8
	compFilterDirs  = 16
	compKeepOrder   = 32
	compMaxValue    = 64
	compRequestCmd  = "__complete"
	compNoDescCmd   = "__completeNoDesc"
)

func directiveString(d int) string {
	var ds []string
	if d&compError != 0 {
		ds = append(ds, "ShellCompDirectiveError")
	}
	if d&compNoSpace != 0 {
		ds = append(ds, "ShellCompDirectiveNoSpace")
	}
	if d&compNoFileComp != 0 {
		ds = append(ds, "ShellCompDirectiveNoFileComp")
	}
	if d&compFilterExt != 0 {
		ds = append(ds, "ShellCompDirectiveFilterFileExt")
	}
	if d&compFilterDirs != 0 {
		ds = append(ds, "ShellCompDirectiveFilterDirs")
	}
	if d&compKeepOrder != 0 {
		ds = append(ds, "ShellCompDirectiveKeepOrder")
	}
	if len(ds) == 0 {
		ds = append(ds, "ShellCompDirectiveDefault")
	}
	if d >= compMaxValue {
		return fmt.Sprintf("ERROR: unexpected ShellCompDirective value: %d", d)
	}
	return strings.Join(ds, ", ")
}

// flagTakesNoValue reports whether a long flag name is a known boolean flag.
func flagTakesNoValue(fs *flagSet, name string) bool {
	f := fs.lookup(name)
	return f != nil && f.IsBool
}

func shortTakesNoValue(fs *flagSet, name string) bool {
	if name == "" {
		return false
	}
	f := fs.shorts[name[0]]
	return f != nil && f.IsBool
}

// stripFlags returns the non-flag arguments (as cobra does when
// searching for subcommands).
func stripFlags(args []string, fs *flagSet) []string {
	commands := []string{}
Loop:
	for len(args) > 0 {
		s := args[0]
		args = args[1:]
		switch {
		case s == "--":
			break Loop
