type yMark struct {
	index, line, column int
}

type yTokenType int

const (
	yNoToken yTokenType = iota
	yStreamStart
	yStreamEnd
	yVersionDirective
	yTagDirective
	yDocumentStart
	yDocumentEnd
	yBlockSequenceStart
	yBlockMappingStart
	yBlockEnd
	yFlowSequenceStart
	yFlowSequenceEnd
	yFlowMappingStart
	yFlowMappingEnd
	yBlockEntry
	yFlowEntry
	yKey
	yValue
	yAlias
	yAnchor
	yTag
	yScalar
)

type yScalarStyle int

const (
	yAnyStyle yScalarStyle = iota
	yPlainStyle
	ySingleQuotedStyle
	yDoubleQuotedStyle
	yLiteralStyle
	yFoldedStyle
)

type yToken struct {
	typ        yTokenType
	start, end yMark
	value      string
	suffix     string // tag suffix
	style      yScalarStyle
}

type ySimpleKey struct {
	possible    bool
	required    bool
	tokenNumber int
	mark        yMark
}

type yErrorKind int

const (
	yNoError yErrorKind = iota
	yScannerError
	yParserError
	yComposerError
)

type yError struct {
	kind        yErrorKind
	context     string
	contextMark yMark
	problem     string
	problemMark yMark
}

type yScanner struct {
	buf []rune
	pos int

	mark yMark

	streamStartProduced bool
	streamEndProduced   bool

	flowLevel int

	tokens       []yToken
	tokensParsed int
	tokenAvail   bool

	indent  int
	indents []int

	simpleKeyAllowed bool
	simpleKeys       []ySimpleKey

	err *yError
}

func newYScanner(input []byte) *yScanner {
	s := string(input)
	// strip a UTF-8 BOM
	s = strings.TrimPrefix(s, "\ufeff")
	runes := make([]rune, 0, utf8.RuneCountInString(s))
	for _, r := range s {
		runes = append(runes, r)
	}
	return &yScanner{buf: runes, indent: -1}
}

func (s *yScanner) at(off int) rune {
	if s.pos+off < len(s.buf) && s.pos+off >= 0 {
		return s.buf[s.pos+off]
	}
	return 0
}

func (s *yScanner) eof(off int) bool { return s.pos+off >= len(s.buf) }

func isZ(r rune, eof bool) bool { return eof || r == 0 }

func (s *yScanner) isBlankAt(off int) bool {
	r := s.at(off)
	return !s.eof(off) && (r == ' ' || r == '\t')
}

func (s *yScanner) isBreakAt(off int) bool {
	if s.eof(off) {
		return false
	}
	r := s.at(off)
	return r == '\r' || r == '\n' || r == '\u0085' || r == '\u2028' || r == '\u2029'
}

func (s *yScanner) isBreakZAt(off int) bool { return s.eof(off) || s.isBreakAt(off) }

func (s *yScanner) isBlankZAt(off int) bool {
	return s.eof(off) || s.isBlankAt(off) || s.isBreakAt(off)
}

func (s *yScanner) isAlphaAt(off int) bool {
	if s.eof(off) {
		return false
	}
	r := s.at(off)
	return (r >= '0' && r <= '9') || (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') || r == '_' || r == '-'
}

func (s *yScanner) skip() {
	s.mark.index++
	s.mark.column++
	s.pos++
}

func (s *yScanner) skipLine() {
	if s.at(0) == '\r' && s.at(1) == '\n' && !s.eof(1) {
		s.mark.index += 2
		s.mark.column = 0
		s.mark.line++
		s.pos += 2
	} else if s.isBreakAt(0) {
		s.mark.index++
		s.mark.column = 0
		s.mark.line++
		s.pos++
	}
}

// read appends the current character to b and advances.
func (s *yScanner) read(b []rune) []rune {
	b = append(b, s.at(0))
	s.skip()
	return b
}

// readLine reads a line break, normalising it.
func (s *yScanner) readLine(b []rune) []rune {
	r := s.at(0)
	if r == '\r' && s.at(1) == '\n' && !s.eof(1) {
		b = append(b, '\n')
		s.pos += 2
		s.mark.index += 2
	} else if r == '\r' || r == '\n' || r == '\u0085' {
		b = append(b, '\n')
		s.pos++
		s.mark.index++
	} else if r == '\u2028' || r == '\u2029' {
		b = append(b, r)
		s.pos++
		s.mark.index++
	} else {
		return b
	}
	s.mark.column = 0
	s.mark.line++
	return b
}

func (s *yScanner) setScannerError(context string, contextMark yMark, problem string) bool {
	s.err = &yError{kind: yScannerError, context: context, contextMark: contextMark, problem: problem, problemMark: s.mark}
	return false
}

// peekToken returns the next token without consuming it.
func (s *yScanner) peekToken() *yToken {
	if s.err != nil {
		return nil
	}
	if !s.tokenAvail {
		if !s.fetchMoreTokens() {
			return nil
		}
	}
	if len(s.tokens) == 0 {
		return nil
	}
	return &s.tokens[0]
}

func (s *yScanner) skipToken() {
	s.tokenAvail = false
	s.tokensParsed++
	if s.tokens[0].typ == yStreamEnd {
		s.streamEndProduced = true
	}
	s.tokens = s.tokens[1:]
}

func (s *yScanner) fetchMoreTokens() bool {
	for {
		need := false
		if len(s.tokens) == 0 {
			need = true
		} else {
			if !s.staleSimpleKeys() {
				return false
			}
			for i := range s.simpleKeys {
				sk := &s.simpleKeys[i]
				if sk.possible && sk.tokenNumber == s.tokensParsed {
					need = true
					break
				}
			}
		}
		if !need {
			break
		}
		if s.streamEndProduced {
			break
		}
		if !s.fetchNextToken() {
			return false
		}
		if len(s.tokens) > 0 && s.tokens[len(s.tokens)-1].typ == yStreamEnd {
			// nothing more can be produced
			s.streamEndProduced = true
		}
	}
	s.tokenAvail = true
	return true
}

func (s *yScanner) insertToken(pos int, t yToken) {
	if pos < 0 || pos >= len(s.tokens) {
		s.tokens = append(s.tokens, t)
		return
	}
	s.tokens = append(s.tokens, yToken{})
	copy(s.tokens[pos+1:], s.tokens[pos:])
	s.tokens[pos] = t
}

func (s *yScanner) fetchNextToken() bool {
	if !s.streamStartProduced {
		s.indent = -1
		s.simpleKeyAllowed = true
		s.simpleKeys = append(s.simpleKeys, ySimpleKey{})
		s.streamStartProduced = true
		s.tokens = append(s.tokens, yToken{typ: yStreamStart, start: s.mark, end: s.mark})
		return true
	}
	if !s.scanToNextToken() {
		return false
	}
	if !s.staleSimpleKeys() {
		return false
	}
	s.unrollIndent(s.mark.column)

	if s.eof(0) {
		return s.fetchStreamEnd()
	}
	c := s.at(0)
	if s.mark.column == 0 && c == '%' {
		return s.fetchDirective()
	}
	if s.mark.column == 0 && c == '-' && s.at(1) == '-' && s.at(2) == '-' && s.isBlankZAt(3) && !s.eof(2) {
		return s.fetchDocumentIndicator(yDocumentStart)
	}
	if s.mark.column == 0 && c == '.' && s.at(1) == '.' && s.at(2) == '.' && s.isBlankZAt(3) && !s.eof(2) {
		return s.fetchDocumentIndicator(yDocumentEnd)
	}
	switch c {
	case '[':
		return s.fetchFlowCollectionStart(yFlowSequenceStart)
	case '{':
		return s.fetchFlowCollectionStart(yFlowMappingStart)
	case ']':
		return s.fetchFlowCollectionEnd(yFlowSequenceEnd)
	case '}':
		return s.fetchFlowCollectionEnd(yFlowMappingEnd)
	case ',':
		return s.fetchFlowEntry()
	}
	if c == '-' && s.isBlankZAt(1) {
		return s.fetchBlockEntry()
	}
	if c == '?' && (s.flowLevel > 0 || s.isBlankZAt(1)) {
		return s.fetchKey()
	}
	if c == ':' && (s.flowLevel > 0 || s.isBlankZAt(1)) {
		return s.fetchValue()
	}
	switch c {
	case '*':
		return s.fetchAnchor(yAlias)
	case '&':
		return s.fetchAnchor(yAnchor)
	case '!':
		return s.fetchTag()
	}
	if c == '|' && s.flowLevel == 0 {
		return s.fetchBlockScalar(true)
	}
	if c == '>' && s.flowLevel == 0 {
		return s.fetchBlockScalar(false)
	}
	if c == '\'' {
		return s.fetchFlowScalar(true)
	}
	if c == '"' {
		return s.fetchFlowScalar(false)
	}
	if !(s.isBlankZAt(0) || strings.ContainsRune("-?:,[]{}#&*!|>'\"%@`", c)) ||
		(c == '-' && !s.isBlankAt(1)) ||
		(s.flowLevel == 0 && (c == '?' || c == ':') && !s.isBlankZAt(1)) {
		return s.fetchPlainScalar()
	}
	return s.setScannerError("while scanning for the next token", s.mark, "found character that cannot start any token")
}

func (s *yScanner) staleSimpleKeys() bool {
	for i := range s.simpleKeys {
		sk := &s.simpleKeys[i]
		if sk.possible && (sk.mark.line < s.mark.line || sk.mark.index+1024 < s.mark.index) {
			if sk.required {
				return s.setScannerError("while scanning a simple key", sk.mark, "could not find expected ':'")
			}
			sk.possible = false
		}
	}
	return true
}

func (s *yScanner) saveSimpleKey() bool {
	required := s.flowLevel == 0 && s.indent == s.mark.column
	if s.simpleKeyAllowed {
		sk := ySimpleKey{possible: true, required: required, tokenNumber: s.tokensParsed + len(s.tokens), mark: s.mark}
		if !s.removeSimpleKey() {
			return false
		}
		s.simpleKeys[len(s.simpleKeys)-1] = sk
	}
	return true
}

func (s *yScanner) removeSimpleKey() bool {
	i := len(s.simpleKeys) - 1
	if s.simpleKeys[i].possible {
		if s.simpleKeys[i].required {
			return s.setScannerError("while scanning a simple key", s.simpleKeys[i].mark, "could not find expected ':'")
		}
	}
	s.simpleKeys[i].possible = false
	return true
}

func (s *yScanner) increaseFlowLevel() {
	s.simpleKeys = append(s.simpleKeys, ySimpleKey{})
	s.flowLevel++
}

func (s *yScanner) decreaseFlowLevel() {
	if s.flowLevel > 0 {
		s.flowLevel--
		s.simpleKeys = s.simpleKeys[:len(s.simpleKeys)-1]
	}
}

func (s *yScanner) rollIndent(column, number int, typ yTokenType, mark yMark) {
	if s.flowLevel > 0 {
		return
	}
	if s.indent < column {
		s.indents = append(s.indents, s.indent)
		s.indent = column
		t := yToken{typ: typ, start: mark, end: mark}
		if number == -1 {
			s.tokens = append(s.tokens, t)
		} else {
			s.insertToken(number-s.tokensParsed, t)
		}
	}
}

func (s *yScanner) unrollIndent(column int) {
	if s.flowLevel > 0 {
		return
	}
	for s.indent > column {
		s.tokens = append(s.tokens, yToken{typ: yBlockEnd, start: s.mark, end: s.mark})
		s.indent = s.indents[len(s.indents)-1]
		s.indents = s.indents[:len(s.indents)-1]
	}
}

func (s *yScanner) fetchStreamEnd() bool {
	if s.mark.column != 0 {
		s.mark.column = 0
		s.mark.line++
	}
	s.unrollIndent(-1)
	if !s.removeSimpleKey() {
		return false
	}
	s.simpleKeyAllowed = false
	s.tokens = append(s.tokens, yToken{typ: yStreamEnd, start: s.mark, end: s.mark})
	return true
}

func (s *yScanner) fetchDirective() bool {
	s.unrollIndent(-1)
	if !s.removeSimpleKey() {
		return false
	}
	s.simpleKeyAllowed = false
	start := s.mark
	s.skip()
	var name []rune
	for s.isAlphaAt(0) {
		name = s.read(name)
	}
	if len(name) == 0 {
		return s.setScannerError("while scanning a directive", start, "could not find expected directive name")
	}
	if !s.isBlankZAt(0) {
		return s.setScannerError("while scanning a directive", start, "found unexpected non-alphabetical character")
	}
	typ := yNoToken
	switch string(name) {
	case "YAML":
		typ = yVersionDirective
	case "TAG":
		typ = yTagDirective
	}
	// skip the rest of the line
	for !s.isBreakZAt(0) {
		if s.at(0) == '#' {
			break
		}
		s.skip()
	}
	for !s.isBreakZAt(0) {
		s.skip()
	}
	if typ == yNoToken {
		// unknown directives are ignored
		return true
	}
	s.tokens = append(s.tokens, yToken{typ: typ, start: start, end: s.mark})
	return true
}

func (s *yScanner) fetchDocumentIndicator(typ yTokenType) bool {
	s.unrollIndent(-1)
	if !s.removeSimpleKey() {
		return false
	}
	s.simpleKeyAllowed = false
	start := s.mark
	s.skip()
	s.skip()
	s.skip()
	s.tokens = append(s.tokens, yToken{typ: typ, start: start, end: s.mark})
	return true
}

func (s *yScanner) fetchFlowCollectionStart(typ yTokenType) bool {
	if !s.saveSimpleKey() {
		return false
	}
	s.increaseFlowLevel()
	s.simpleKeyAllowed = true
	start := s.mark
	s.skip()
	s.tokens = append(s.tokens, yToken{typ: typ, start: start, end: s.mark})
	return true
}

func (s *yScanner) fetchFlowCollectionEnd(typ yTokenType) bool {
	if !s.removeSimpleKey() {
		return false
	}
	s.decreaseFlowLevel()
	s.simpleKeyAllowed = false
	start := s.mark
	s.skip()
	s.tokens = append(s.tokens, yToken{typ: typ, start: start, end: s.mark})
	return true
}

func (s *yScanner) fetchFlowEntry() bool {
	if !s.removeSimpleKey() {
		return false
	}
	s.simpleKeyAllowed = true
	start := s.mark
	s.skip()
	s.tokens = append(s.tokens, yToken{typ: yFlowEntry, start: start, end: s.mark})
	return true
}

func (s *yScanner) fetchBlockEntry() bool {
	if s.flowLevel == 0 {
		if !s.simpleKeyAllowed {
			return s.setScannerError("", s.mark, "block sequence entries are not allowed in this context")
		}
		s.rollIndent(s.mark.column, -1, yBlockSequenceStart, s.mark)
	}
	if !s.removeSimpleKey() {
		return false
	}
	s.simpleKeyAllowed = true
	start := s.mark
	s.skip()
	s.tokens = append(s.tokens, yToken{typ: yBlockEntry, start: start, end: s.mark})
	return true
}

func (s *yScanner) fetchKey() bool {
	if s.flowLevel == 0 {
		if !s.simpleKeyAllowed {
			return s.setScannerError("", s.mark, "mapping keys are not allowed in this context")
		}
		s.rollIndent(s.mark.column, -1, yBlockMappingStart, s.mark)
	}
	if !s.removeSimpleKey() {
		return false
	}
	s.simpleKeyAllowed = s.flowLevel == 0
	start := s.mark
	s.skip()
	s.tokens = append(s.tokens, yToken{typ: yKey, start: start, end: s.mark})
	return true
}

func (s *yScanner) fetchValue() bool {
	sk := &s.simpleKeys[len(s.simpleKeys)-1]
	if sk.possible {
		t := yToken{typ: yKey, start: sk.mark, end: sk.mark}
		s.insertToken(sk.tokenNumber-s.tokensParsed, t)
		s.rollIndent(sk.mark.column, sk.tokenNumber, yBlockMappingStart, sk.mark)
		sk.possible = false
		s.simpleKeyAllowed = false
	} else {
		if s.flowLevel == 0 {
			if !s.simpleKeyAllowed {
				return s.setScannerError("", s.mark, "mapping values are not allowed in this context")
			}
			s.rollIndent(s.mark.column, -1, yBlockMappingStart, s.mark)
		}
		s.simpleKeyAllowed = s.flowLevel == 0
	}
	start := s.mark
	s.skip()
	s.tokens = append(s.tokens, yToken{typ: yValue, start: start, end: s.mark})
	return true
}

func (s *yScanner) fetchAnchor(typ yTokenType) bool {
	if !s.saveSimpleKey() {
		return false
	}
	s.simpleKeyAllowed = false
	start := s.mark
	s.skip()
	var name []rune
	for s.isAlphaAt(0) {
		name = s.read(name)
	}
	c := s.at(0)
	if len(name) == 0 || !(s.isBlankZAt(0) || c == '?' || c == ':' || c == ',' || c == ']' || c == '}' || c == '%' || c == '@' || c == '`') {
		ctx := "while scanning an anchor"
		if typ == yAlias {
			ctx = "while scanning an alias"
		}
		return s.setScannerError(ctx, start, "did not find expected alphabetic or numeric character")
	}
	s.tokens = append(s.tokens, yToken{typ: typ, start: start, end: s.mark, value: string(name)})
	return true
}

func (s *yScanner) fetchTag() bool {
	if !s.saveSimpleKey() {
		return false
	}
	s.simpleKeyAllowed = false
	start := s.mark
	var handle, suffix []rune
	if s.at(1) == '<' {
		s.skip()
		s.skip()
		for !s.isBlankZAt(0) && s.at(0) != '>' {
			suffix = s.read(suffix)
		}
		if s.at(0) != '>' {
			return s.setScannerError("while scanning a tag", start, "did not find the expected '>'")
		}
		s.skip()
	} else {
		handle = s.read(handle) // '!'
		for s.isAlphaAt(0) {
			handle = s.read(handle)
		}
		if s.at(0) == '!' {
			handle = s.read(handle)
		} else {
			// no secondary '!', the whole thing is a suffix of '!'
			suffix = append(suffix, handle[1:]...)
			handle = []rune{'!'}
		}
		for !s.isBlankZAt(0) && !(s.flowLevel > 0 && strings.ContainsRune(",[]{}", s.at(0))) {
			suffix = s.read(suffix)
		}
		if len(suffix) == 0 && string(handle) == "!" {
			// a lone '!' is the non-specific tag
		}
	}
	if !s.isBlankZAt(0) {
		if s.flowLevel == 0 || s.at(0) != ',' {
			return s.setScannerError("while scanning a tag", start, "did not find expected whitespace or line break")
		}
	}
	s.tokens = append(s.tokens, yToken{typ: yTag, start: start, end: s.mark, value: string(handle), suffix: string(suffix)})
	return true
}

func (s *yScanner) scanToNextToken() bool {
	for {
		// skip BOM? not needed
		for s.at(0) == ' ' && !s.eof(0) || ((s.flowLevel > 0 || !s.simpleKeyAllowed) && s.at(0) == '\t' && !s.eof(0)) {
			s.skip()
		}
		if s.at(0) == '#' && !s.eof(0) {
			for !s.isBreakZAt(0) {
				s.skip()
			}
		}
		if s.isBreakAt(0) {
			s.skipLine()
			if s.flowLevel == 0 {
				s.simpleKeyAllowed = true
			}
		} else {
			break
		}
	}
	return true
}

func (s *yScanner) fetchFlowScalar(single bool) bool {
	if !s.saveSimpleKey() {
		return false
	}
	s.simpleKeyAllowed = false
	start := s.mark
	s.skip() // opening quote
	var str, leadingBreak, trailingBreaks, whitespaces []rune
	for {
		if s.mark.column == 0 && !s.eof(2) &&
			((s.at(0) == '-' && s.at(1) == '-' && s.at(2) == '-') || (s.at(0) == '.' && s.at(1) == '.' && s.at(2) == '.')) &&
			s.isBlankZAt(3) {
			return s.setScannerError("while scanning a quoted scalar", start, "found unexpected document indicator")
		}
		if s.eof(0) {
			return s.setScannerError("while scanning a quoted scalar", start, "found unexpected end of stream")
		}
		leadingBlanks := false
		for !s.isBlankZAt(0) {
			c := s.at(0)
			if single && c == '\'' && s.at(1) == '\'' && !s.eof(1) {
				str = append(str, '\'')
				s.skip()
				s.skip()
			} else if c == '\'' && single {
				break
			} else if c == '"' && !single {
				break
			} else if !single && c == '\\' && s.isBreakAt(1) {
				s.skip()
				s.skipLine()
				leadingBlanks = true
				break
			} else if !single && c == '\\' {
				codeLength := 0
				esc := s.at(1)
				switch esc {
				case '0':
					str = append(str, 0)
				case 'a':
					str = append(str, '\x07')
				case 'b':
					str = append(str, '\x08')
				case 't', '\t':
					str = append(str, '\t')
				case 'n':
					str = append(str, '\n')
				case 'v':
					str = append(str, '\x0b')
				case 'f':
					str = append(str, '\x0c')
				case 'r':
					str = append(str, '\r')
				case 'e':
					str = append(str, '\x1b')
				case ' ':
					str = append(str, ' ')
				case '"':
					str = append(str, '"')
				case '/':
					str = append(str, '/')
				case '\\':
					str = append(str, '\\')
				case 'N':
					str = append(str, '\u0085')
				case '_':
					str = append(str, '\u00a0')
				case 'L':
					str = append(str, '\u2028')
				case 'P':
					str = append(str, '\u2029')
				case 'x':
					codeLength = 2
				case 'u':
					codeLength = 4
				case 'U':
					codeLength = 8
				default:
					return s.setScannerError("while parsing a quoted scalar", start, "found unknown escape character")
				}
				s.skip()
				s.skip()
				if codeLength > 0 {
					value := 0
					for k := 0; k < codeLength; k++ {
						h := s.at(k)
						var d int
						switch {
						case h >= '0' && h <= '9' && !s.eof(k):
							d = int(h - '0')
						case h >= 'a' && h <= 'f':
							d = int(h-'a') + 10
						case h >= 'A' && h <= 'F':
							d = int(h-'A') + 10
						default:
							return s.setScannerError("while parsing a quoted scalar", start, "did not find expected hexdecimal number")
						}
						value = value<<4 + d
					}
					if (value >= 0xD800 && value <= 0xDFFF) || value > 0x10FFFF {
						return s.setScannerError("while parsing a quoted scalar", start, "found invalid Unicode character escape code")
					}
					for k := 0; k < codeLength; k++ {
						s.skip()
					}
					str = append(str, rune(value))
				}
			} else {
				str = s.read(str)
			}
		}
		if s.eof(0) {
			return s.setScannerError("while scanning a quoted scalar", start, "found unexpected end of stream")
		}
		if (single && s.at(0) == '\'') || (!single && s.at(0) == '"') {
			break
		}
		for s.isBlankAt(0) || s.isBreakAt(0) {
			if s.isBlankAt(0) {
				if !leadingBlanks {
					whitespaces = s.read(whitespaces)
				} else {
					s.skip()
				}
			} else {
				if !leadingBlanks {
					whitespaces = whitespaces[:0]
					leadingBreak = s.readLine(leadingBreak[:0])
					leadingBlanks = true
				} else {
					trailingBreaks = s.readLine(trailingBreaks)
				}
			}
		}
		if leadingBlanks {
			if len(leadingBreak) > 0 && leadingBreak[0] == '\n' {
				if len(trailingBreaks) == 0 {
					str = append(str, ' ')
				} else {
					str = append(str, trailingBreaks...)
				}
			} else {
				str = append(str, leadingBreak...)
				str = append(str, trailingBreaks...)
			}
			trailingBreaks = trailingBreaks[:0]
			leadingBreak = leadingBreak[:0]
		} else {
			str = append(str, whitespaces...)
			whitespaces = whitespaces[:0]
		}
	}
	s.skip() // closing quote
	style := yDoubleQuotedStyle
	if single {
		style = ySingleQuotedStyle
	}
	s.tokens = append(s.tokens, yToken{typ: yScalar, start: start, end: s.mark, value: string(str), style: style})
	return true
}

func (s *yScanner) fetchPlainScalar() bool {
	if !s.saveSimpleKey() {
		return false
	}
	s.simpleKeyAllowed = false
	var str, leadingBreak, trailingBreaks, whitespaces []rune
	leadingBlanks := false
	indent := s.indent + 1
	start := s.mark
	end := s.mark
	for {
		if s.mark.column == 0 && !s.eof(2) &&
			((s.at(0) == '-' && s.at(1) == '-' && s.at(2) == '-') || (s.at(0) == '.' && s.at(1) == '.' && s.at(2) == '.')) &&
			s.isBlankZAt(3) {
			break
		}
		if s.at(0) == '#' && !s.eof(0) {
			break
		}
		for !s.isBlankZAt(0) {
			c := s.at(0)
			if s.flowLevel > 0 && c == ':' && (s.at(1) == ',' || s.at(1) == '?' || s.at(1) == '[' || s.at(1) == ']' || s.at(1) == '{' || s.at(1) == '}') {
				break
			}
			if (c == ':' && s.isBlankZAt(1)) || (s.flowLevel > 0 && (c == ',' || c == '[' || c == ']' || c == '{' || c == '}')) {
				break
			}
			if leadingBlanks || len(whitespaces) > 0 {
				if leadingBlanks {
					if len(leadingBreak) > 0 && leadingBreak[0] == '\n' {
						if len(trailingBreaks) == 0 {
							str = append(str, ' ')
						} else {
							str = append(str, trailingBreaks...)
						}
					} else {
						str = append(str, leadingBreak...)
						str = append(str, trailingBreaks...)
					}
					trailingBreaks = trailingBreaks[:0]
					leadingBreak = leadingBreak[:0]
					leadingBlanks = false
				} else {
					str = append(str, whitespaces...)
					whitespaces = whitespaces[:0]
				}
			}
			str = s.read(str)
			end = s.mark
		}
		if !(s.isBlankAt(0) || s.isBreakAt(0)) {
			break
		}
		for s.isBlankAt(0) || s.isBreakAt(0) {
			if s.isBlankAt(0) {
				if leadingBlanks && s.mark.column < indent && s.at(0) == '\t' {
					return s.setScannerError("while scanning a plain scalar", start, "found a tab character that violates indentation")
				}
				if !leadingBlanks {
					whitespaces = s.read(whitespaces)
				} else {
					s.skip()
				}
			} else {
				if !leadingBlanks {
					whitespaces = whitespaces[:0]
					leadingBreak = s.readLine(leadingBreak[:0])
					leadingBlanks = true
				} else {
					trailingBreaks = s.readLine(trailingBreaks)
				}
			}
		}
		if s.flowLevel == 0 && s.mark.column < indent {
			break
		}
	}
	s.tokens = append(s.tokens, yToken{typ: yScalar, start: start, end: end, value: string(str), style: yPlainStyle})
	if leadingBlanks {
		s.simpleKeyAllowed = true
	}
	return true
}

func (s *yScanner) fetchBlockScalar(literal bool) bool {
	if !s.removeSimpleKey() {
		return false
	}
	s.simpleKeyAllowed = true
	start := s.mark
	s.skip() // indicator
	chomping := 0
	increment := 0
	if s.at(0) == '+' || s.at(0) == '-' {
		if s.at(0) == '+' {
			chomping = 1
		} else {
			chomping = -1
		}
		s.skip()
		if s.at(0) >= '0' && s.at(0) <= '9' {
			if s.at(0) == '0' {
				return s.setScannerError("while scanning a block scalar", start, "found an indentation indicator equal to 0")
			}
			increment = int(s.at(0) - '0')
			s.skip()
		}
	} else if s.at(0) >= '0' && s.at(0) <= '9' && !s.eof(0) {
		if s.at(0) == '0' {
			return s.setScannerError("while scanning a block scalar", start, "found an indentation indicator equal to 0")
		}
		increment = int(s.at(0) - '0')
		s.skip()
		if s.at(0) == '+' || s.at(0) == '-' {
			if s.at(0) == '+' {
				chomping = 1
			} else {
				chomping = -1
			}
			s.skip()
		}
	}
	for s.isBlankAt(0) {
		s.skip()
	}
	if s.at(0) == '#' && !s.eof(0) {
		for !s.isBreakZAt(0) {
			s.skip()
		}
	}
	if !s.isBreakZAt(0) {
		return s.setScannerError("while scanning a block scalar", start, "did not find expected comment or line break")
	}
	if s.isBreakAt(0) {
		s.skipLine()
	}
	end := s.mark
	indent := 0
	if increment > 0 {
		if s.indent >= 0 {
			indent = s.indent + increment
		} else {
			indent = increment
		}
	}
	var str, leadingBreak, trailingBreaks []rune
	// scan leading line breaks and determine indentation
	scanBreaks := func() bool {
		maxIndent := 0
		end = s.mark
		for {
			for (indent == 0 || s.mark.column < indent) && s.isBlankAt(0) && s.at(0) == ' ' {
				s.skip()
			}
			if s.mark.column > maxIndent {
				maxIndent = s.mark.column
			}
			if (indent == 0 || s.mark.column < indent) && s.at(0) == '\t' && !s.eof(0) {
				return s.setScannerError("while scanning a block scalar", start, "found a tab character where an indentation space is expected")
			}
			if !s.isBreakAt(0) {
				break
			}
			trailingBreaks = s.readLine(trailingBreaks)
			end = s.mark
		}
		if indent == 0 {
			indent = maxIndent
			if indent < s.indent+1 {
				indent = s.indent + 1
			}
			if indent < 1 {
				indent = 1
			}
		}
		return true
	}
	if !scanBreaks() {
		return false
	}
	leadingBlank := false
	trailingBlank := false
	for s.mark.column == indent && !s.eof(0) {
		trailingBlank = s.isBlankAt(0)
		if !literal && len(leadingBreak) > 0 && leadingBreak[0] == '\n' && !leadingBlank && !trailingBlank {
			if len(trailingBreaks) == 0 {
				str = append(str, ' ')
			}
			leadingBreak = leadingBreak[:0]
		} else {
			str = append(str, leadingBreak...)
			leadingBreak = leadingBreak[:0]
		}
		str = append(str, trailingBreaks...)
		trailingBreaks = trailingBreaks[:0]
		leadingBlank = s.isBlankAt(0)
		for !s.isBreakZAt(0) {
			str = s.read(str)
		}
		if s.eof(0) {
			break
		}
		leadingBreak = s.readLine(leadingBreak)
		if !scanBreaks() {
			return false
		}
	}
	if chomping != -1 {
		str = append(str, leadingBreak...)
	}
	if chomping == 1 {
		str = append(str, trailingBreaks...)
	}
	style := yLiteralStyle
	if !literal {
		style = yFoldedStyle
	}
	s.tokens = append(s.tokens, yToken{typ: yScalar, start: start, end: end, value: string(str), style: style})
	return true
}
EOF"}

actions.command:
cat > /workspace/cmd/cheat/yaml_scan.go <<'EOF'
package main

// A YAML scanner modelled on the classic token-based design: the input is
// split into tokens (with "simple key" detection and indentation tracking),
// which a small state-machine parser turns into events.

import (
	"strings"
	"unicode/utf8"
)

type yMark struct {
	index, line, column int
}

type yTokenType int

const (
	yNoToken yTokenType = iota
	yStreamStart
	yStreamEnd
	yVersionDirective
	yTagDirective
	yDocumentStart
	yDocumentEnd
	yBlockSequenceStart
	yBlockMappingStart
	yBlockEnd
	yFlowSequenceStart
	yFlowSequenceEnd
	yFlowMappingStart
	yFlowMappingEnd
	yBlockEntry
	yFlowEntry
	yKey
	yValue
	yAlias
	yAnchor
	yTag
	yScalar
)

type yScalarStyle int

const (
	yAnyStyle yScalarStyle = iota
	yPlainStyle
	ySingleQuotedStyle
	yDoubleQuotedStyle
	yLiteralStyle
	yFoldedStyle
)

type yToken struct {
	typ        yTokenType
	start, end yMark
	value      string
	suffix     string // tag suffix
	style      yScalarStyle
}

type ySimpleKey struct {
	possible    bool
	required    bool
	tokenNumber int
	mark        yMark
}

type yErrorKind int

const (
	yNoError yErrorKind = iota
	yScannerError
	yParserError
	yComposerError
)

type yError struct {
	kind        yErrorKind
	context     string
	contextMark yMark
	problem     string
	problemMark yMark
}

type yScanner struct {
	buf []rune
	pos int

	mark yMark

	streamStartProduced bool
	streamEndProduced   bool

	flowLevel int

	tokens       []yToken
	tokensParsed int
	tokenAvail   bool

	indent  int
	indents []int

	simpleKeyAllowed bool
	simpleKeys       []ySimpleKey

	err *yError
}

func newYScanner(input []byte) *yScanner {
	s := string(input)
	// strip a UTF-8 BOM
	s = strings.TrimPrefix(s, "\ufeff")
	runes := make([]rune, 0, utf8.RuneCountInString(s))
	for _, r := range s {
		runes = append(runes, r)
	}
	return &yScanner{buf: runes, indent: -1}
}

func (s *yScanner) at(off int) rune {
	if s.pos+off < len(s.buf) && s.pos+off >= 0 {
		return s.buf[s.pos+off]
	}
	return 0
}

func (s *yScanner) eof(off int) bool { return s.pos+off >= len(s.buf) }

func isZ(r rune, eof bool) bool { return eof || r == 0 }

func (s *yScanner) isBlankAt(off int) bool {
	r := s.at(off)
	return !s.eof(off) && (r == ' ' || r == '\t')
}

func (s *yScanner) isBreakAt(off int) bool {
	if s.eof(off) {
		return false
	}
	r := s.at(off)
	return r == '\r' || r == '\n' || r == '\u0085' || r == '\u2028' || r == '\u2029'
}

func (s *yScanner) isBreakZAt(off int) bool { return s.eof(off) || s.isBreakAt(off) }

func (s *yScanner) isBlankZAt(off int) bool {
	return s.eof(off) || s.isBlankAt(off) || s.isBreakAt(off)
}

func (s *yScanner) isAlphaAt(off int) bool {
	if s.eof(off) {
		return false
	}
	r := s.at(off)
	return (r >= '0' && r <= '9') || (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') || r == '_' || r == '-'
}

func (s *yScanner) skip() {
	s.mark.index++
	s.mark.column++
	s.pos++
}

func (s *yScanner) skipLine() {
	if s.at(0) == '\r' && s.at(1) == '\n' && !s.eof(1) {
		s.mark.index += 2
		s.mark.column = 0
		s.mark.line++
		s.pos += 2
	} else if s.isBreakAt(0) {
		s.mark.index++
		s.mark.column = 0
		s.mark.line++
		s.pos++
	}
}

// read appends the current character to b and advances.
func (s *yScanner) read(b []rune) []rune {
	b = append(b, s.at(0))
	s.skip()
	return b
}

// readLine reads a line break, normalising it.
func (s *yScanner) readLine(b []rune) []rune {
	r := s.at(0)
	if r == '\r' && s.at(1) == '\n' && !s.eof(1) {
		b = append(b, '\n')
		s.pos += 2
		s.mark.index += 2
	} else if r == '\r' || r == '\n' || r == '\u0085' {
		b = append(b, '\n')
		s.pos++
		s.mark.index++
	} else if r == '\u2028' || r == '\u2029' {
		b = append(b, r)
		s.pos++
		s.mark.index++
	} else {
		return b
	}
	s.mark.column = 0
	s.mark.line++
	return b
}

func (s *yScanner) setScannerError(context string, contextMark yMark, problem string) bool {
	s.err = &yError{kind: yScannerError, context: context, contextMark: contextMark, problem: problem, problemMark: s.mark}
	return false
}

// peekToken returns the next token without consuming it.
func (s *yScanner) peekToken() *yToken {
	if s.err != nil {
		return nil
	}
	if !s.tokenAvail {
		if !s.fetchMoreTokens() {
			return nil
		}
	}
	if len(s.tokens) == 0 {
		return nil
	}
	return &s.tokens[0]
}

func (s *yScanner) skipToken() {
	s.tokenAvail = false
	s.tokensParsed++
	if s.tokens[0].typ == yStreamEnd {
		s.streamEndProduced = true
	}
	s.tokens = s.tokens[1:]
}

func (s *yScanner) fetchMoreTokens() bool {
	for {
		need := false
		if len(s.tokens) == 0 {
			need = true
		} else {
			if !s.staleSimpleKeys() {
				return false
			}
			for i := range s.simpleKeys {
				sk := &s.simpleKeys[i]
				if sk.possible && sk.tokenNumber == s.tokensParsed {
					need = true
					break
				}
			}
		}
		if !need {
			break
		}
		if s.streamEndProduced {
			break
		}
		if !s.fetchNextToken() {
			return false
		}
		if len(s.tokens) > 0 && s.tokens[len(s.tokens)-1].typ == yStreamEnd {
			// nothing more can be produced
			s.streamEndProduced = true
		}
	}
	s.tokenAvail = true
	return true
}

func (s *yScanner) insertToken(pos int, t yToken) {
	if pos < 0 || pos >= len(s.tokens) {
		s.tokens = append(s.tokens, t)
		return
	}
	s.tokens = append(s.tokens, yToken{})
	copy(s.tokens[pos+1:], s.tokens[pos:])
	s.tokens[pos] = t
}

func (s *yScanner) fetchNextToken() bool {
	if !s.streamStartProduced {
		s.indent = -1
		s.simpleKeyAllowed = true
		s.simpleKeys = append(s.simpleKeys, ySimpleKey{})
		s.streamStartProduced = true
		s.tokens = append(s.tokens, yToken{typ: yStreamStart, start: s.mark, end: s.mark})
		return true
	}
	if !s.scanToNextToken() {
		return false
	}
	if !s.staleSimpleKeys() {
		return false
	}
	s.unrollIndent(s.mark.column)

	if s.eof(0) {
		return s.fetchStreamEnd()
	}
	c := s.at(0)
	if s.mark.column == 0 && c == '%' {
		return s.fetchDirective()
	}
	if s.mark.column == 0 && c == '-' && s.at(1) == '-' && s.at(2) == '-' && s.isBlankZAt(3) && !s.eof(2) {
		return s.fetchDocumentIndicator(yDocumentStart)
	}
	if s.mark.column == 0 && c == '.' && s.at(1) == '.' && s.at(2) == '.' && s.isBlankZAt(3) && !s.eof(2) {
		return s.fetchDocumentIndicator(yDocumentEnd)
	}
	switch c {
	case '[':
		return s.fetchFlowCollectionStart(yFlowSequenceStart)
	case '{':
		return s.fetchFlowCollectionStart(yFlowMappingStart)
	case ']':
		return s.fetchFlowCollectionEnd(yFlowSequenceEnd)
	case '}':
		return s.fetchFlowCollectionEnd(yFlowMappingEnd)
	case ',':
		return s.fetchFlowEntry()
	}
	if c == '-' && s.isBlankZAt(1) {
		return s.fetchBlockEntry()
	}
	if c == '?' && (s.flowLevel > 0 || s.isBlankZAt(1)) {
		return s.fetchKey()
	}
	if c == ':' && (s.flowLevel > 0 || s.isBlankZAt(1)) {
		return s.fetchValue()
	}
	switch c {
	case '*':
		return s.fetchAnchor(yAlias)
	case '&':
		return s.fetchAnchor(yAnchor)
	case '!':
		return s.fetchTag()
	}
	if c == '|' && s.flowLevel == 0 {
		return s.fetchBlockScalar(true)
	}
	if c == '>' && s.flowLevel == 0 {
		return s.fetchBlockScalar(false)
	}
	if c == '\'' {
		return s.fetchFlowScalar(true)
	}
	if c == '"' {
		return s.fetchFlowScalar(false)
	}
	if !(s.isBlankZAt(0) || strings.ContainsRune("-?:,[]{}#&*!|>'\"%@`", c)) ||
		(c == '-' && !s.isBlankAt(1)) ||
		(s.flowLevel == 0 && (c == '?' || c == ':') && !s.isBlankZAt(1)) {
		return s.fetchPlainScalar()
	}
	return s.setScannerError("while scanning for the next token", s.mark, "found character that cannot start any token")
}

func (s *yScanner) staleSimpleKeys() bool {
	for i := range s.simpleKeys {
		sk := &s.simpleKeys[i]
		if sk.possible && (sk.mark.line < s.mark.line || sk.mark.index+1024 < s.mark.index) {
			if sk.required {
				return s.setScannerError("while scanning a simple key", sk.mark, "could not find expected ':'")
			}
			sk.possible = false
		}
	}
	return true
}

func (s *yScanner) saveSimpleKey() bool {
	required := s.flowLevel == 0 && s.indent == s.mark.column
	if s.simpleKeyAllowed {
		sk := ySimpleKey{possible: true, required: required, tokenNumber: s.tokensParsed + len(s.tokens), mark: s.mark}
		if !s.removeSimpleKey() {
			return false
		}
		s.simpleKeys[len(s.simpleKeys)-1] = sk
	}
	return true
}

func (s *yScanner) removeSimpleKey() bool {
	i := len(s.simpleKeys) - 1
	if s.simpleKeys[i].possible {
		if s.simpleKeys[i].required {
			return s.setScannerError("while scanning a simple key", s.simpleKeys[i].mark, "could not find expected ':'")
		}
	}
	s.simpleKeys[i].possible = false
	return true
}

func (s *yScanner) increaseFlowLevel() {
	s.simpleKeys = append(s.simpleKeys, ySimpleKey{})
	s.flowLevel++
}

func (s *yScanner) decreaseFlowLevel() {
	if s.flowLevel > 0 {
		s.flowLevel--
		s.simpleKeys = s.simpleKeys[:len(s.simpleKeys)-1]
	}
}

func (s *yScanner) rollIndent(column, number int, typ yTokenType, mark yMark) {
	if s.flowLevel > 0 {
		return
	}
	if s.indent < column {
		s.indents = append(s.indents, s.indent)
		s.indent = column
		t := yToken{typ: typ, start: mark, end: mark}
		if number == -1 {
			s.tokens = append(s.tokens, t)
		} else {
			s.insertToken(number-s.tokensParsed, t)
		}
	}
}

func (s *yScanner) unrollIndent(column int) {
	if s.flowLevel > 0 {
		return
	}
	for s.indent > column {
		s.tokens = append(s.tokens, yToken{typ: yBlockEnd, start: s.mark, end: s.mark})
		s.indent = s.indents[len(s.indents)-1]
		s.indents = s.indents[:len(s.indents)-1]
	}
}

func (s *yScanner) fetchStreamEnd() bool {
	if s.mark.column != 0 {
		s.mark.column = 0
		s.mark.line++
	}
	s.unrollIndent(-1)
	if !s.removeSimpleKey() {
		return false
	}
	s.simpleKeyAllowed = false
	s.tokens = append(s.tokens, yToken{typ: yStreamEnd, start: s.mark, end: s.mark})
	return true
}

func (s *yScanner) fetchDirective() bool {
	s.unrollIndent(-1)
	if !s.removeSimpleKey() {
		return false
	}
	s.simpleKeyAllowed = false
	start := s.mark
	s.skip()
	var name []rune
	for s.isAlphaAt(0) {
		name = s.read(name)
	}
	if len(name) == 0 {
		return s.setScannerError("while scanning a directive", start, "could not find expected directive name")
	}
	if !s.isBlankZAt(0) {
		return s.setScannerError("while scanning a directive", start, "found unexpected non-alphabetical character")
	}
	typ := yNoToken
	switch string(name) {
	case "YAML":
		typ = yVersionDirective
	case "TAG":
		typ = yTagDirective
	}
	// skip the rest of the line
	for !s.isBreakZAt(0) {
		if s.at(0) == '#' {
			break
		}
		s.skip()
	}
	for !s.isBreakZAt(0) {
		s.skip()
	}
	if typ == yNoToken {
		// unknown directives are ignored
		return true
	}
	s.tokens = append(s.tokens, yToken{typ: typ, start: start, end: s.mark})
	return true
}

