func (s *yScanner) fetchTag() bool {
	if !s.saveSimpleKey() {
		return false
	}
	s.simpleKeyAllowed = false
	start := s.mark
	var handle, suffix []rune
	if s.at(1) == '<' {
		s.skip()
		s.skip()
		for !s.isBlankZAt(0) && s.at(0) != '>' {
			suffix = s.read(suffix)
		}
		if s.at(0) != '>' {
			return s.setScannerError("while scanning a tag", start, "did not find the expected '>'")
		}
		s.skip()
	} else {
		handle = s.read(handle) // '!'
		for s.isAlphaAt(0) {
			handle = s.read(handle)
		}
		if s.at(0) == '!' {
			handle = s.read(handle)
		} else {
			// no secondary '!', the whole thing is a suffix of '!'
			suffix = append(suffix, handle[1:]...)
			handle = []rune{'!'}
		}
		for !s.isBlankZAt(0) && !(s.flowLevel > 0 && strings.ContainsRune(",[]{}", s.at(0))) {
			suffix = s.read(suffix)
		}
		if len(suffix) == 0 && string(handle) == "!" {
			// a lone '!' is the non-specific tag
		}
	}
	if !s.isBlankZAt(0) {
		if s.flowLevel == 0 || s.at(0) != ',' {
			return s.setScannerError("while scanning a tag", start, "did not find expected whitespace or line break")
		}
	}
	s.tokens = append(s.tokens, yToken{typ: yTag, start: start, end: s.mark, value: string(handle), suffix: string(suffix)})
	return true
}

func (s *yScanner) scanToNextToken() bool {
	for {
