	style := yDoubleQuotedStyle
	if single {
		style = ySingleQuotedStyle
	}
	s.tokens = append(s.tokens, yToken{typ: yScalar, start: start, end: s.mark, value: string(str), style: style})
	return true
}

func (s *yScanner) fetchPlainScalar() bool {
	if !s.saveSimpleKey() {
		return false
	}
	s.simpleKeyAllowed = false
	var str, leadingBreak, trailingBreaks, whitespaces []rune
	leadingBlanks := false
	indent := s.indent + 1
	start := s.mark
	end := s.mark
	for {
		if s.mark.column == 0 && !s.eof(2) &&
			((s.at(0) == '-' && s.at(1) == '-' && s.at(2) == '-') || (s.at(0) == '.' && s.at(1) == '.' && s.at(2) == '.')) &&
			s.isBlankZAt(3) {
			break
		}
		if s.at(0) == '#' && !s.eof(0) {
			break
		}
		for !s.isBlankZAt(0) {
			c := s.at(0)
			if s.flowLevel > 0 && c == ':' && (s.at(1) == ',' || s.at(1) == '?' || s.at(1) == '[' || s.at(1) == ']' || s.at(1) == '{' || s.at(1) == '}') {
				break
			}
			if (c == ':' && s.isBlankZAt(1)) || (s.flowLevel > 0 && (c == ',' || c == '[' || c == ']' || c == '{' || c == '}')) {
				break
			}
			if leadingBlanks || len(whitespaces) > 0 {
				if leadingBlanks {
					if len(leadingBreak) > 0 && leadingBreak[0] == '\n' {
						if len(trailingBreaks) == 0 {
							str = append(str, ' ')
						} else {
							str = append(str, trailingBreaks...)
						}
					} else {
						str = append(str, leadingBreak...)
						str = append(str, trailingBreaks...)
					}
					trailingBreaks = trailingBreaks[:0]
					leadingBreak = leadingBreak[:0]
					leadingBlanks = false
				} else {
					str = append(str, whitespaces...)
					whitespaces = whitespaces[:0]
				}
			}
			str = s.read(str)
			end = s.mark
		}
		if !(s.isBlankAt(0) || s.isBreakAt(0)) {
			break
		}
		for s.isBlankAt(0) || s.isBreakAt(0) {
			if s.isBlankAt(0) {
