func newYParser(input []byte) *yParser {
	return &yParser{sc: newYScanner(input), state: ypsStreamStart}
}

func (p *yParser) peek() *yToken {
	t := p.sc.peekToken()
	if t == nil && p.sc.err != nil {
		p.err = p.sc.err
	}
	return t
}

func (p *yParser) skip() { p.sc.skipToken() }

func (p *yParser) setParserError(problem string, mark yMark) bool {
	p.err = &yError{kind: yParserError, problem: problem, problemMark: mark}
	return false
}

func (p *yParser) setParserErrorContext(context string, contextMark yMark, problem string, problemMark yMark) bool {
	p.err = &yError{kind: yParserError, context: context, contextMark: contextMark, problem: problem, problemMark: problemMark}
	return false
}

func (p *yParser) pushState(s yParserState) { p.states = append(p.states, s) }

func (p *yParser) popState() yParserState {
	s := p.states[len(p.states)-1]
	p.states = p.states[:len(p.states)-1]
	return s
}

func (p *yParser) popMark() yMark {
	m := p.marks[len(p.marks)-1]
	p.marks = p.marks[:len(p.marks)-1]
	return m
}

// next produces the next event.
func (p *yParser) next(ev *yEvent) bool {
	if p.err != nil || p.state == ypsEnd {
		return false
	}
	switch p.state {
	case ypsStreamStart:
		t := p.peek()
		if t == nil {
			return false
		}
		if t.typ != yStreamStart {
			return p.setParserError("did not find expected <stream-start>", t.start)
		}
		p.state = ypsImplicitDocumentStart
		*ev = yEvent{typ: yevStreamStart, start: t.start, end: t.end}
		p.skip()
		return true
	case ypsImplicitDocumentStart:
		return p.parseDocumentStart(ev, true)
	case ypsDocumentStart:
		return p.parseDocumentStart(ev, false)
	case ypsDocumentContent:
		return p.parseDocumentContent(ev)
	case ypsDocumentEnd:
		return p.parseDocumentEnd(ev)
	case ypsBlockNode:
		return p.parseNode(ev, true, false)
	case ypsBlockSequenceFirstEntry:
		return p.parseBlockSequenceEntry(ev, true)
	case ypsBlockSequenceEntry:
		return p.parseBlockSequenceEntry(ev, false)
	case ypsIndentlessSequenceEntry:
		return p.parseIndentlessSequenceEntry(ev)
	case ypsBlockMappingFirstKey:
		return p.parseBlockMappingKey(ev, true)
	case ypsBlockMappingKey:
		return p.parseBlockMappingKey(ev, false)
	case ypsBlockMappingValue:
		return p.parseBlockMappingValue(ev)
	case ypsFlowSequenceFirstEntry:
		return p.parseFlowSequenceEntry(ev, true)
	case ypsFlowSequenceEntry:
		return p.parseFlowSequenceEntry(ev, false)
	case ypsFlowSequenceEntryMappingKey:
		return p.parseFlowSequenceEntryMappingKey(ev)
	case ypsFlowSequenceEntryMappingValue:
		return p.parseFlowSequenceEntryMappingValue(ev)
	case ypsFlowSequenceEntryMappingEnd:
		return p.parseFlowSequenceEntryMappingEnd(ev)
	case ypsFlowMappingFirstKey:
		return p.parseFlowMappingKey(ev, true)
	case ypsFlowMappingKey:
		return p.parseFlowMappingKey(ev, false)
	case ypsFlowMappingValue:
		return p.parseFlowMappingValue(ev, false)
	case ypsFlowMappingEmptyValue:
		return p.parseFlowMappingValue(ev, true)
	}
	return false
}

func (p *yParser) processDirectives() bool {
	for {
		t := p.peek()
		if t == nil {
			return false
		}
		if t.typ != yVersionDirective && t.typ != yTagDirective {
			return true
		}
		p.skip()
	}
}

func (p *yParser) parseDocumentStart(ev *yEvent, implicit bool) bool {
	t := p.peek()
	if t == nil {
		return false
	}
	if !implicit {
		for t.typ == yDocumentEnd {
			p.skip()
			t = p.peek()
			if t == nil {
				return false
			}
		}
	}
	if implicit && t.typ != yVersionDirective && t.typ != yTagDirective && t.typ != yDocumentStart && t.typ != yStreamEnd {
		p.pushState(ypsDocumentEnd)
		p.state = ypsBlockNode
		*ev = yEvent{typ: yevDocumentStart, start: t.start, end: t.start, implicit: true}
		return true
	}
	if t.typ != yStreamEnd {
		start := t.start
		if !p.processDirectives() {
			return false
		}
		t = p.peek()
		if t == nil {
			return false
		}
		if t.typ != yDocumentStart {
			return p.setParserError("did not find expected <document start>", t.start)
		}
		p.pushState(ypsDocumentEnd)
		p.state = ypsDocumentContent
		*ev = yEvent{typ: yevDocumentStart, start: start, end: t.end}
		p.skip()
		return true
	}
	p.state = ypsEnd
	*ev = yEvent{typ: yevStreamEnd, start: t.start, end: t.end}
	p.skip()
	return true
}

func (p *yParser) parseDocumentContent(ev *yEvent) bool {
	t := p.peek()
	if t == nil {
		return false
	}
	switch t.typ {
	case yVersionDirective, yTagDirective, yDocumentStart, yDocumentEnd, yStreamEnd:
		p.state = p.popState()
		return p.processEmptyScalar(ev, t.start)
	}
	return p.parseNode(ev, true, false)
}

func (p *yParser) parseDocumentEnd(ev *yEvent) bool {
	t := p.peek()
	if t == nil {
		return false
	}
	start, end := t.start, t.start
	implicit := true
	if t.typ == yDocumentEnd {
		end = t.end
		p.skip()
		implicit = false
	}
	p.state = ypsDocumentStart
	*ev = yEvent{typ: yevDocumentEnd, start: start, end: end, implicit: implicit}
	return true
}

func (p *yParser) parseNode(ev *yEvent, block, indentlessSequence bool) bool {
	t := p.peek()
	if t == nil {
		return false
	}
	if t.typ == yAlias {
		p.state = p.popState()
		*ev = yEvent{typ: yevAlias, start: t.start, end: t.end, anchor: t.value}
		p.skip()
		return true
	}
	start, end := t.start, t.start
	tagMark := t.start
	var anchor, tagHandle, tagSuffix string
	hasTag := false
	if t.typ == yAnchor {
		anchor = t.value
		start, end = t.start, t.end
		p.skip()
		t = p.peek()
		if t == nil {
			return false
		}
		if t.typ == yTag {
			hasTag = true
			tagHandle, tagSuffix = t.value, t.suffix
			tagMark = t.start
			end = t.end
			p.skip()
			t = p.peek()
			if t == nil {
				return false
			}
		}
	} else if t.typ == yTag {
		hasTag = true
		tagHandle, tagSuffix = t.value, t.suffix
		start, tagMark = t.start, t.start
		end = t.end
		p.skip()
		t = p.peek()
		if t == nil {
			return false
		}
		if t.typ == yAnchor {
			anchor = t.value
			end = t.end
			p.skip()
			t = p.peek()
			if t == nil {
				return false
			}
		}
	}
	tag := ""
	if hasTag {
		if tagHandle == "" {
			tag = tagSuffix
		} else {
			switch tagHandle {
			case "!!":
				tag = "tag:yaml.org,2002:" + tagSuffix
			case "!":
				tag = "!" + tagSuffix
			default:
				if prefix, ok := p.tagDirectives[tagHandle]; ok {
					tag = prefix + tagSuffix
				} else {
					return p.setParserErrorContext("while parsing a node", start, "found undefined tag handle", tagMark)
				}
			}
		}
	}
	implicit := tag == ""
	if indentlessSequence && t.typ == yBlockEntry {
		end = t.end
		p.state = ypsIndentlessSequenceEntry
		*ev = yEvent{typ: yevSequenceStart, start: start, end: end, anchor: anchor, tag: tag, implicit: implicit}
		return true
	}
	if t.typ == yScalar {
		end = t.end
		p.state = p.popState()
		*ev = yEvent{typ: yevScalar, start: start, end: end, anchor: anchor, tag: tag, value: t.value, style: t.style,
			implicit: (t.style == yPlainStyle && tag == "") || tag == "!"}
		if t.style == yPlainStyle && tag == "" {
			ev.implicit = true
		}
		if start == (yMark{}) && anchor == "" && !hasTag {
			ev.start = t.start
		}
		if anchor == "" && !hasTag {
			ev.start = t.start
		}
		p.skip()
		return true
	}
	if t.typ == yFlowSequenceStart {
		end = t.end
		p.state = ypsFlowSequenceFirstEntry
		if anchor == "" && !hasTag {
			start = t.start
		}
		*ev = yEvent{typ: yevSequenceStart, start: start, end: end, anchor: anchor, tag: tag, implicit: implicit}
		return true
	}
	if t.typ == yFlowMappingStart {
		end = t.end
		p.state = ypsFlowMappingFirstKey
		if anchor == "" && !hasTag {
			start = t.start
		}
		*ev = yEvent{typ: yevMappingStart, start: start, end: end, anchor: anchor, tag: tag, implicit: implicit}
		return true
	}
	if block && t.typ == yBlockSequenceStart {
		end = t.end
		p.state = ypsBlockSequenceFirstEntry
		if anchor == "" && !hasTag {
			start = t.start
		}
		*ev = yEvent{typ: yevSequenceStart, start: start, end: end, anchor: anchor, tag: tag, implicit: implicit}
		return true
	}
	if block && t.typ == yBlockMappingStart {
		end = t.end
		p.state = ypsBlockMappingFirstKey
		if anchor == "" && !hasTag {
			start = t.start
		}
		*ev = yEvent{typ: yevMappingStart, start: start, end: end, anchor: anchor, tag: tag, implicit: implicit}
		return true
	}
	if anchor != "" || hasTag {
		p.state = p.popState()
		*ev = yEvent{typ: yevScalar, start: start, end: end, anchor: anchor, tag: tag, implicit: implicit, style: yPlainStyle}
		return true
	}
	context := "while parsing a flow node"
	if block {
		context = "while parsing a block node"
	}
	return p.setParserErrorContext(context, start, "did not find expected node content", t.start)
}

func (p *yParser) parseBlockSequenceEntry(ev *yEvent, first bool) bool {
	if first {
		t := p.peek()
		if t == nil {
			return false
		}
		p.marks = append(p.marks, t.start)
		p.skip()
	}
	t := p.peek()
	if t == nil {
		return false
	}
	if t.typ == yBlockEntry {
		mark := t.end
		p.skip()
		t = p.peek()
		if t == nil {
			return false
		}
		if t.typ != yBlockEntry && t.typ != yBlockEnd {
			p.pushState(ypsBlockSequenceEntry)
			return p.parseNode(ev, true, false)
		}
		p.state = ypsBlockSequenceEntry
		return p.processEmptyScalar(ev, mark)
	}
	if t.typ == yBlockEnd {
		p.state = p.popState()
		p.popMark()
		*ev = yEvent{typ: yevSequenceEnd, start: t.start, end: t.end}
		p.skip()
		return true
	}
	return p.setParserErrorContext("while parsing a block collection", p.popMark(), "did not find expected '-' indicator", t.start)
}

func (p *yParser) parseIndentlessSequenceEntry(ev *yEvent) bool {
	t := p.peek()
	if t == nil {
		return false
	}
	if t.typ == yBlockEntry {
		mark := t.end
		p.skip()
		t = p.peek()
		if t == nil {
			return false
		}
		if t.typ != yBlockEntry && t.typ != yKey && t.typ != yValue && t.typ != yBlockEnd {
			p.pushState(ypsIndentlessSequenceEntry)
			return p.parseNode(ev, true, false)
		}
		p.state = ypsIndentlessSequenceEntry
		return p.processEmptyScalar(ev, mark)
	}
	p.state = p.popState()
	*ev = yEvent{typ: yevSequenceEnd, start: t.start, end: t.start}
	return true
}

func (p *yParser) parseBlockMappingKey(ev *yEvent, first bool) bool {
	if first {
		t := p.peek()
		if t == nil {
			return false
		}
		p.marks = append(p.marks, t.start)
		p.skip()
	}
	t := p.peek()
	if t == nil {
		return false
	}
	if t.typ == yKey {
		mark := t.end
		p.skip()
		t = p.peek()
		if t == nil {
			return false
		}
		if t.typ != yKey && t.typ != yValue && t.typ != yBlockEnd {
			p.pushState(ypsBlockMappingValue)
			return p.parseNode(ev, true, true)
		}
		p.state = ypsBlockMappingValue
		return p.processEmptyScalar(ev, mark)
	}
	if t.typ == yBlockEnd {
		p.state = p.popState()
		p.popMark()
		*ev = yEvent{typ: yevMappingEnd, start: t.start, end: t.end}
		p.skip()
		return true
	}
	return p.setParserErrorContext("while parsing a block mapping", p.popMark(), "did not find expected key", t.start)
}

func (p *yParser) parseBlockMappingValue(ev *yEvent) bool {
	t := p.peek()
	if t == nil {
		return false
	}
	if t.typ == yValue {
		mark := t.end
		p.skip()
		t = p.peek()
		if t == nil {
			return false
		}
		if t.typ != yKey && t.typ != yValue && t.typ != yBlockEnd {
			p.pushState(ypsBlockMappingKey)
			return p.parseNode(ev, true, true)
		}
		p.state = ypsBlockMappingKey
		return p.processEmptyScalar(ev, mark)
	}
	p.state = ypsBlockMappingKey
	return p.processEmptyScalar(ev, t.start)
}

func (p *yParser) parseFlowSequenceEntry(ev *yEvent, first bool) bool {
	if first {
		t := p.peek()
		if t == nil {
			return false
		}
		p.marks = append(p.marks, t.start)
		p.skip()
	}
	t := p.peek()
	if t == nil {
		return false
	}
	if t.typ != yFlowSequenceEnd {
		if !first {
			if t.typ == yFlowEntry {
				p.skip()
				t = p.peek()
				if t == nil {
					return false
				}
			} else {
				return p.setParserErrorContext("while parsing a flow sequence", p.popMark(), "did not find expected ',' or ']'", t.start)
			}
		}
		if t.typ == yKey {
			p.state = ypsFlowSequenceEntryMappingKey
			*ev = yEvent{typ: yevMappingStart, start: t.start, end: t.end, implicit: true}
			p.skip()
			return true
		} else if t.typ != yFlowSequenceEnd {
			p.pushState(ypsFlowSequenceEntry)
			return p.parseNode(ev, false, false)
		}
	}
	p.state = p.popState()
	p.popMark()
	*ev = yEvent{typ: yevSequenceEnd, start: t.start, end: t.end}
	p.skip()
	return true
}

func (p *yParser) parseFlowSequenceEntryMappingKey(ev *yEvent) bool {
	t := p.peek()
	if t == nil {
		return false
	}
	if t.typ != yValue && t.typ != yFlowEntry && t.typ != yFlowSequenceEnd {
		p.pushState(ypsFlowSequenceEntryMappingValue)
		return p.parseNode(ev, false, false)
	}
	mark := t.end
	p.state = ypsFlowSequenceEntryMappingValue
	return p.processEmptyScalar(ev, mark)
}

func (p *yParser) parseFlowSequenceEntryMappingValue(ev *yEvent) bool {
	t := p.peek()
	if t == nil {
		return false
	}
	if t.typ == yValue {
		p.skip()
		t = p.peek()
		if t == nil {
			return false
		}
		if t.typ != yFlowEntry && t.typ != yFlowSequenceEnd {
			p.pushState(ypsFlowSequenceEntryMappingEnd)
			return p.parseNode(ev, false, false)
		}
	}
	p.state = ypsFlowSequenceEntryMappingEnd
	return p.processEmptyScalar(ev, t.start)
}

func (p *yParser) parseFlowSequenceEntryMappingEnd(ev *yEvent) bool {
	t := p.peek()
	if t == nil {
		return false
	}
	p.state = ypsFlowSequenceEntry
	*ev = yEvent{typ: yevMappingEnd, start: t.start, end: t.start}
	return true
}

func (p *yParser) parseFlowMappingKey(ev *yEvent, first bool) bool {
	if first {
		t := p.peek()
		if t == nil {
			return false
		}
		p.marks = append(p.marks, t.start)
		p.skip()
	}
	t := p.peek()
	if t == nil {
		return false
	}
	if t.typ != yFlowMappingEnd {
		if !first {
			if t.typ == yFlowEntry {
				p.skip()
				t = p.peek()
				if t == nil {
					return false
				}
			} else {
				return p.setParserErrorContext("while parsing a flow mapping", p.popMark(), "did not find expected ',' or '}'", t.start)
			}
		}
		if t.typ == yKey {
			p.skip()
			t = p.peek()
			if t == nil {
				return false
			}
			if t.typ != yValue && t.typ != yFlowEntry && t.typ != yFlowMappingEnd {
				p.pushState(ypsFlowMappingValue)
				return p.parseNode(ev, false, false)
			}
			p.state = ypsFlowMappingValue
			return p.processEmptyScalar(ev, t.start)
		} else if t.typ != yFlowMappingEnd {
			p.pushState(ypsFlowMappingEmptyValue)
			return p.parseNode(ev, false, false)
		}
	}
	p.state = p.popState()
	p.popMark()
	*ev = yEvent{typ: yevMappingEnd, start: t.start, end: t.end}
	p.skip()
	return true
}

func (p *yParser) parseFlowMappingValue(ev *yEvent, empty bool) bool {
	t := p.peek()
	if t == nil {
		return false
	}
	if empty {
		p.state = ypsFlowMappingKey
		return p.processEmptyScalar(ev, t.start)
	}
	if t.typ == yValue {
		p.skip()
		t = p.peek()
		if t == nil {
			return false
		}
		if t.typ != yFlowEntry && t.typ != yFlowMappingEnd {
			p.pushState(ypsFlowMappingKey)
			return p.parseNode(ev, false, false)
		}
	}
	p.state = ypsFlowMappingKey
	return p.processEmptyScalar(ev, t.start)
}

func (p *yParser) processEmptyScalar(ev *yEvent, mark yMark) bool {
	*ev = yEvent{typ: yevScalar, start: mark, end: mark, implicit: true, style: yPlainStyle}
	return true
}

// ---------------------------------------------------------------------------
// Composition into a node tree.

type yNodeKind int

const (
	yDocumentNode yNodeKind = iota + 1
	ySequenceNode
	yMappingNode
	yScalarNode
	yAliasNode
)

type yNode struct {
	kind    yNodeKind
	style   yScalarStyle
	tag     string
	value   string
	anchor  string
	alias   *yNode
	content []*yNode
	line    int
	column  int
}

type yamlFail struct{ msg string }

type yComposer struct {
	p       *yParser
	ev      yEvent
	have    bool
	anchors map[string]*yNode
}

func (c *yComposer) fail() {
	e := c.p.err
	var line int
	if e.contextMark.line != 0 {
		line = e.contextMark.line
		if e.kind == yScannerError {
			line++
		}
	} else if e.problemMark.line != 0 {
		line = e.problemMark.line
		if e.kind == yScannerError {
			line++
		}
	}
	where := ""
	if line != 0 {
		where = "line " + strconv.Itoa(line) + ": "
	}
	msg := e.problem
	if msg == "" {
		msg = "unknown problem parsing YAML content"
	}
	panic(yamlFail{"yaml: " + where + msg})
}

func (c *yComposer) peek() yEventType {
	if c.have {
		return c.ev.typ
	}
	if !c.p.next(&c.ev) {
		if c.p.err == nil {
			c.p.err = &yError{kind: yParserError, problem: "unknown problem parsing YAML content"}
		}
		c.fail()
	}
	c.have = true
	return c.ev.typ
}

func (c *yComposer) expect(t yEventType) {
	if !c.have {
		if !c.p.next(&c.ev) {
			c.fail()
		}
	}
	if c.ev.typ == yevStreamEnd {
		panic(yamlFail{"yaml: attempted to go past the end of stream; corrupted value?"})
	}
	if c.ev.typ != t {
		panic(yamlFail{fmt.Sprintf("yaml: expected %d event but got %d", t, c.ev.typ)})
	}
	c.have = false
}

func (c *yComposer) node(kind yNodeKind, tag, value string) *yNode {
	n := &yNode{kind: kind, tag: tag, value: value, style: c.ev.style, line: c.ev.start.line + 1, column: c.ev.start.column + 1}
	return n
}

func (c *yComposer) anchor(n *yNode, anchor string) {
	if anchor != "" {
		n.anchor = anchor
		c.anchors[anchor] = n
	}
}

func (c *yComposer) parse() *yNode {
	switch c.peek() {
	case yevScalar:
		return c.scalar()
	case yevAlias:
		return c.aliasNode()
	case yevMappingStart:
		return c.mapping()
	case yevSequenceStart:
		return c.sequence()
	case yevDocumentStart:
		return c.document()
	case yevStreamEnd:
		return nil
	}
	panic(yamlFail{"yaml: unexpected event"})
}

func (c *yComposer) document() *yNode {
	n := c.node(yDocumentNode, "", "")
	c.expect(yevDocumentStart)
	n.content = append(n.content, c.parse())
	if c.peek() != yevDocumentEnd {
		panic(yamlFail{"yaml: expected document end"})
	}
	c.expect(yevDocumentEnd)
	return n
}

func (c *yComposer) aliasNode() *yNode {
	n := c.node(yAliasNode, "", c.ev.anchor)
	n.alias = c.anchors[n.value]
	if n.alias == nil {
		panic(yamlFail{fmt.Sprintf("yaml: unknown anchor '%s' referenced", n.value)})
	}
	c.expect(yevAlias)
	return n
}

func (c *yComposer) scalar() *yNode {
	tag := c.ev.tag
	if tag == "!" {
		tag = ""
	}
	n := c.node(yScalarNode, shortTag(tag), c.ev.value)
	if tag == "" && c.ev.style == yPlainStyle {
		// plain, untagged: resolved later
		n.tag = ""
	}
	if c.ev.tag == "!" {
		n.tag = "!!str"
	}
	c.anchor(n, c.ev.anchor)
	c.expect(yevScalar)
	return n
}

func (c *yComposer) sequence() *yNode {
	n := c.node(ySequenceNode, shortTag(c.ev.tag), "")
	c.anchor(n, c.ev.anchor)
	c.expect(yevSequenceStart)
	for c.peek() != yevSequenceEnd {
		n.content = append(n.content, c.parse())
	}
	c.expect(yevSequenceEnd)
	return n
}

func (c *yComposer) mapping() *yNode {
	n := c.node(yMappingNode, shortTag(c.ev.tag), "")
	c.anchor(n, c.ev.anchor)
	c.expect(yevMappingStart)
	for c.peek() != yevMappingEnd {
		k := c.parse()
		v := c.parse()
		n.content = append(n.content, k, v)
	}
	c.expect(yevMappingEnd)
	return n
}

func shortTag(tag string) string {
	const prefix = "tag:yaml.org,2002:"
	if len(tag) > len(prefix) && tag[:len(prefix)] == prefix {
		return "!!" + tag[len(prefix):]
	}
	return tag
}

// yamlParse parses the first document of input into a node tree.
func yamlParse(input []byte) (doc *yNode, err error) {
	defer func() {
		if r := recover(); r != nil {
			if f, ok := r.(yamlFail); ok {
				err = fmt.Errorf("%s", f.msg)
				return
			}
			panic(r)
		}
	}()
	c := &yComposer{p: newYParser(input), anchors: map[string]*yNode{}}
	// stream start
	if c.peek() != yevStreamStart {
		panic(yamlFail{"yaml: expected stream start"})
	}
	c.have = false
	n := c.parse()
	return n, nil
}
