	l := len(n.content)
	nerrs := len(d.terrors)
	for i := 0; i < l; i += 2 {
		ni := n.content[i]
		for j := i + 2; j < l; j += 2 {
			nj := n.content[j]
			if ni.kind == nj.kind && ni.value == nj.value {
				d.terrors = append(d.terrors, fmt.Sprintf("line %d: mapping key %q already defined at line %d", nj.line, nj.value, ni.line))
			}
		}
	}
	if len(d.terrors) > nerrs {
		return false
	}
	for i := 0; i+1 < l; i += 2 {
		var name string
		if !d.str(n.content[i], &name) {
			continue
		}
		if f, ok := fields[name]; ok {
			f(n.content[i+1])
		}
	}
	return true
}

func (d *yDecoder) err() error {
	if len(d.terrors) > 0 {
		return fmt.Errorf("yaml: unmarshal errors:\n  %s", strings.Join(d.terrors, "\n  "))
	}
	return nil
}

func yamlRoot(buf []byte) (*yNode, error) {
	doc, err := yamlParse(buf)
	if err != nil {
		return nil, err
	}
	if doc == nil || len(doc.content) == 0 {
		return nil, nil
	}
	return doc.content[0], nil
}

func decodeCheatpath(d *yDecoder, n *yNode, cp *Cheatpath) bool {
	return d.structFields(n, "cheatpath.Path", map[string]func(*yNode){
		"name":     func(v *yNode) { d.str(v, &cp.Name) },
		"path":     func(v *yNode) { d.str(v, &cp.Path) },
		"tags":     func(v *yNode) { d.strSlice(v, &cp.Tags) },
		"readonly": func(v *yNode) { d.boolean(v, &cp.ReadOnly) },
	})
}

// decodeConfig unmarshals a config file.
func decodeConfig(buf []byte) (Config, error) {
	var conf Config
	root, err := yamlRoot(buf)
	if err != nil {
		return conf, err
	}
	if root == nil {
		return conf, nil
	}
	d := &yDecoder{}
	d.structFields(root, "config.Config", map[string]func(*yNode){
		"editor":    func(v *yNode) { d.str(v, &conf.Editor) },
		"colorize":  func(v *yNode) { d.boolean(v, &conf.Colorize) },
		"style":     func(v *yNode) { d.str(v, &conf.Style) },
		"formatter": func(v *yNode) { d.str(v, &conf.Formatter) },
		"pager":     func(v *yNode) { d.str(v, &conf.Pager) },
		"cheatpaths": func(v *yNode) {
			v = deref(v)
			switch v.kind {
			case yScalarNode:
				tag, _ := d.nodeTag(v)
				if tag == "!!null" {
					conf.Cheatpaths = nil
					return
				}
				d.terror(v, tag, "[]cheatpath.Path")
			case yMappingNode:
				d.terror(v, "!!map", "[]cheatpath.Path")
			case ySequenceNode:
				out := make([]Cheatpath, 0, len(v.content))
				for _, item := range v.content {
					var cp Cheatpath
					if decodeCheatpath(d, item, &cp) {
						out = append(out, cp)
					}
				}
				conf.Cheatpaths = out
			}
		},
	})
	return conf, d.err()
}

// decodeFrontmatter unmarshals a sheet's frontmatter.
func decodeFrontmatter(buf []byte) (Frontmatter, error) {
	var fm Frontmatter
	root, err := yamlRoot(buf)
	if err != nil {
		return fm, err
	}
	if root == nil {
		return fm, nil
	}
	d := &yDecoder{}
	d.structFields(root, "sheet.frontmatter", map[string]func(*yNode){
		"syntax": func(v *yNode) { d.str(v, &fm.Syntax) },
		"tags":   func(v *yNode) { d.strSlice(v, &fm.Tags) },
	})
	return fm, d.err()
}
