// Package rx implements a small backtracking regular expression engine with
// the features needed by the syntax highlighter: lookaround assertions,
// backreferences, lazy quantifiers and inline flags.
package rx

import (
	"fmt"
	"strconv"
	"strings"
	"unicode"
)

type nodeKind int

const (
	nLit nodeKind = iota
	nAny
	nClass
	nConcat
	nAlt
	nRepeat
	nGroup
	nNonCap
	nLookahead
	nNegLookahead
	nLookbehind
	nNegLookbehind
	nBol
	nEol
	nStart  // \A
	nEnd    // \z
	nEndZ   // \Z
	nWordB  // \b
	nNWordB // \B
	nBackref
	nEmpty
	nG // \G
)

type classItem struct {
	lo, hi rune
	fn     func(rune) bool
	neg    bool // for fn items: negated
}

type node struct {
	kind     nodeKind
	r        rune
	fold     bool // case insensitive literal/class
	items    []classItem
	negated  bool
	subs     []*node
	min, max int // max -1 = inf
	lazy     bool
	group    int
	dotAll   bool
	multi    bool
}

// Regexp is a compiled expression.
type Regexp struct {
	root    *node
	ngroups int
	names   map[string]int
	src     string
}

type flags struct {
	i, s, m, x bool
}

type parser struct {
	src     []rune
	pos     int
	ngroups int
	names   map[string]int
}

// MustCompile compiles or panics.
func MustCompile(s string) *Regexp {
	re, err := Compile(s)
	if err != nil {
		panic(err)
	}
	return re
}

// Compile parses a regular expression.
func Compile(s string) (*Regexp, error) {
	p := &parser{src: []rune(s), names: map[string]int{}}
	f := flags{}
	n, err := p.parseAlt(&f)
	if err != nil {
		return nil, err
	}
	if p.pos < len(p.src) {
		return nil, fmt.Errorf("rx: unexpected ) in %q", s)
	}
	return &Regexp{root: n, ngroups: p.ngroups, names: p.names, src: s}, nil
}

func (p *parser) more() bool { return p.pos < len(p.src) }
func (p *parser) peek() rune {
	if p.pos < len(p.src) {
		return p.src[p.pos]
	}
	return 0
}

func (p *parser) parseAlt(f *flags) (*node, error) {
	var alts []*node
	for {
		c, err := p.parseConcat(f)
		if err != nil {
			return nil, err
		}
		alts = append(alts, c)
		if p.more() && p.peek() == '|' {
			p.pos++
			continue
		}
		break
	}
	if len(alts) == 1 {
		return alts[0], nil
	}
	return &node{kind: nAlt, subs: alts}, nil
}

func (p *parser) parseConcat(f *flags) (*node, error) {
	var items []*node
	for p.more() {
		c := p.peek()
		if c == '|' || c == ')' {
			break
		}
		atom, err := p.parseAtom(f)
		if err != nil {
			return nil, err
		}
		if atom == nil {
			continue
		}
		atom, err = p.parseQuant(atom, f)
		if err != nil {
			return nil, err
		}
		items = append(items, atom)
	}
	if len(items) == 1 {
		return items[0], nil
	}
	return &node{kind: nConcat, subs: items}, nil
}

func (p *parser) parseQuant(atom *node, f *flags) (*node, error) {
	for p.more() {
		if f.x {
			p.skipExtended()
			if !p.more() {
				break
			}
		}
		c := p.peek()
		min, max := -2, -2
		switch c {
		case '*':
			min, max = 0, -1
			p.pos++
		case '+':
			min, max = 1, -1
			p.pos++
		case '?':
			min, max = 0, 1
			p.pos++
		case '{':
			// try {n}, {n,}, {n,m}
			save := p.pos
			p.pos++
			n1, ok1 := p.parseInt()
			if !ok1 {
				p.pos = save
				return atom, nil
			}
			if p.peek() == '}' {
				p.pos++
				min, max = n1, n1
			} else if p.peek() == ',' {
				p.pos++
				if p.peek() == '}' {
					p.pos++
					min, max = n1, -1
				} else {
					n2, ok2 := p.parseInt()
					if !ok2 || p.peek() != '}' {
						p.pos = save
						return atom, nil
					}
					p.pos++
					min, max = n1, n2
				}
			} else {
				p.pos = save
				return atom, nil
			}
		default:
			return atom, nil
		}
		lazy := false
		if p.more() && p.peek() == '?' {
			lazy = true
			p.pos++
		} else if p.more() && p.peek() == '+' {
			// possessive: treat as greedy
			p.pos++
		}
		atom = &node{kind: nRepeat, subs: []*node{atom}, min: min, max: max, lazy: lazy}
	}
	return atom, nil
}

func (p *parser) parseInt() (int, bool) {
	start := p.pos
	for p.more() && p.peek() >= '0' && p.peek() <= '9' {
		p.pos++
	}
	if p.pos == start {
		return 0, false
	}
	n, _ := strconv.Atoi(string(p.src[start:p.pos]))
	return n, true
}

func (p *parser) skipExtended() {
	for p.more() {
		c := p.peek()
		if c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\f' || c == '\v' {
			p.pos++
			continue
		}
		if c == '#' {
			for p.more() && p.peek() != '\n' {
				p.pos++
			}
			continue
		}
		break
	}
}

func (p *parser) parseAtom(f *flags) (*node, error) {
	if f.x {
		p.skipExtended()
		if !p.more() || p.peek() == '|' || p.peek() == ')' {
			return nil, nil
		}
	}
	c := p.peek()
	switch c {
	case '(':
		return p.parseGroup(f)
	case '[':
		return p.parseClass(f)
	case '.':
		p.pos++
		return &node{kind: nAny, dotAll: f.s}, nil
	case '^':
		p.pos++
		return &node{kind: nBol, multi: f.m}, nil
	case '$':
		p.pos++
		return &node{kind: nEol, multi: f.m}, nil
	case '\\':
		return p.parseEscape(f)
	}
	p.pos++
	return &node{kind: nLit, r: c, fold: f.i}, nil
}

func (p *parser) parseGroup(f *flags) (*node, error) {
	p.pos++ // (
	kind := nGroup
	group := 0
	nf := *f
	if p.peek() == '?' {
		p.pos++
		c := p.peek()
		switch {
		case c == ':':
			p.pos++
			kind = nNonCap
		case c == '=':
			p.pos++
			kind = nLookahead
		case c == '!':
			p.pos++
			kind = nNegLookahead
		case c == '<' && p.pos+1 < len(p.src) && p.src[p.pos+1] == '=':
			p.pos += 2
			kind = nLookbehind
		case c == '<' && p.pos+1 < len(p.src) && p.src[p.pos+1] == '!':
			p.pos += 2
			kind = nNegLookbehind
		case c == 'P' || c == '<' || c == '\'':
			// named group
			if c == 'P' {
				p.pos++
			}
			open := p.peek()
			close := '>'
			if open == '\'' {
				close = '\''
			}
			p.pos++
			start := p.pos
			for p.more() && p.peek() != close {
				p.pos++
			}
			name := string(p.src[start:p.pos])
			p.pos++
			p.ngroups++
			group = p.ngroups
			p.names[name] = group
			kind = nGroup
		case c == '>':
			// atomic group: approximate as non-capturing
			p.pos++
			kind = nNonCap
		case c == '#':
			for p.more() && p.peek() != ')' {
				p.pos++
			}
			p.pos++
			return nil, nil
		default:
			// inline flags
			on := true
			for p.more() {
				c = p.peek()
				if c == ')' {
					p.pos++
					*f = nf
					return nil, nil
				}
				if c == ':' {
					p.pos++
					kind = nNonCap
					break
				}
				switch c {
				case '-':
					on = false
				case 'i':
					nf.i = on
				case 's':
					nf.s = on
				case 'm':
					nf.m = on
				case 'x':
					nf.x = on
				case 'u', 'U', 'n':
				default:
					return nil, fmt.Errorf("rx: bad flag %q", c)
				}
				p.pos++
			}
		}
	} else {
		p.ngroups++
		group = p.ngroups
	}
	sub, err := p.parseAlt(&nf)
	if err != nil {
		return nil, err
	}
	if p.peek() != ')' {
		return nil, fmt.Errorf("rx: missing )")
	}
	p.pos++
	return &node{kind: kind, subs: []*node{sub}, group: group}, nil
}

func isWordRune(r rune) bool {
	return r == '_' || unicode.IsLetter(r) || unicode.IsDigit(r) || unicode.Is(unicode.Mn, r) || unicode.Is(unicode.Pc, r)
}

func isSpaceRune(r rune) bool {
	switch r {
	case ' ', '\t', '\n', '\r', '\f', '\v', 0x85:
		return true
	}
	return unicode.Is(unicode.Z, r)
}

func isDigitRune(r rune) bool { return unicode.Is(unicode.Nd, r) }

func (p *parser) parseEscapeRune() (rune, func(rune) bool, bool, error) {
	// returns rune or class fn (with negation)
	p.pos++ // backslash
	if !p.more() {
		return '\\', nil, false, nil
	}
	c := p.peek()
	p.pos++
	switch c {
	case 'w':
		return 0, isWordRune, false, nil
	case 'W':
		return 0, isWordRune, true, nil
	case 's':
		return 0, isSpaceRune, false, nil
	case 'S':
		return 0, isSpaceRune, true, nil
	case 'd':
		return 0, isDigitRune, false, nil
	case 'D':
		return 0, isDigitRune, true, nil
	case 'n':
		return '\n', nil, false, nil
	case 't':
		return '\t', nil, false, nil
	case 'r':
		return '\r', nil, false, nil
	case 'f':
		return '\f', nil, false, nil
	case 'v':
		return '\v', nil, false, nil
	case 'e':
		return 0x1b, nil, false, nil
	case 'a':
		return 7, nil, false, nil
	case '0':
		return 0, nil, false, nil
	case 'x':
		if p.peek() == '{' {
			p.pos++
			start := p.pos
			for p.more() && p.peek() != '}' {
				p.pos++
			}
			v, _ := strconv.ParseUint(string(p.src[start:p.pos]), 16, 32)
			p.pos++
			return rune(v), nil, false, nil
		}
		if p.pos+2 <= len(p.src) {
			v, err := strconv.ParseUint(string(p.src[p.pos:p.pos+2]), 16, 32)
			if err == nil {
				p.pos += 2
				return rune(v), nil, false, nil
			}
		}
		return 'x', nil, false, nil
	case 'u':
		if p.pos+4 <= len(p.src) {
			v, err := strconv.ParseUint(string(p.src[p.pos:p.pos+4]), 16, 32)
			if err == nil {
				p.pos += 4
				return rune(v), nil, false, nil
			}
		}
		return 'u', nil, false, nil
	case 'p', 'P':
		neg := c == 'P'
		var name string
		if p.peek() == '{' {
			p.pos++
			start := p.pos
			for p.more() && p.peek() != '}' {
				p.pos++
			}
			name = string(p.src[start:p.pos])
			p.pos++
		} else {
			name = string(p.peek())
			p.pos++
		}
		tab := unicode.Categories[name]
		if tab == nil {
			tab = unicode.Scripts[name]
		}
		if tab == nil {
			if strings.HasPrefix(name, "Is") {
				tab = unicode.Scripts[name[2:]]
			}
		}
		if tab == nil {
			return 0, func(rune) bool { return false }, neg, nil
		}
		t := tab
		return 0, func(r rune) bool { return unicode.Is(t, r) }, neg, nil
	}
	return c, nil, false, nil
}

func (p *parser) parseEscape(f *flags) (*node, error) {
	if p.pos+1 < len(p.src) {
		c := p.src[p.pos+1]
		switch c {
		case 'A':
			p.pos += 2
			return &node{kind: nStart}, nil
		case 'z':
			p.pos += 2
			return &node{kind: nEnd}, nil
		case 'Z':
			p.pos += 2
			return &node{kind: nEndZ}, nil
		case 'G':
			p.pos += 2
			return &node{kind: nG}, nil
		case 'b':
			p.pos += 2
			return &node{kind: nWordB}, nil
		case 'B':
			p.pos += 2
			return &node{kind: nNWordB}, nil
		}
		if c >= '1' && c <= '9' {
			p.pos++
			n, _ := p.parseInt()
			return &node{kind: nBackref, group: n, fold: f.i}, nil
		}
		if c == 'k' && p.pos+2 < len(p.src) && (p.src[p.pos+2] == '<' || p.src[p.pos+2] == '\'') {
			p.pos += 3
			start := p.pos
			for p.more() && p.peek() != '>' && p.peek() != '\'' {
				p.pos++
			}
			name := string(p.src[start:p.pos])
			p.pos++
			return &node{kind: nBackref, group: p.names[name], fold: f.i}, nil
		}
	}
	r, fn, neg, err := p.parseEscapeRune()
	if err != nil {
		return nil, err
	}
	if fn != nil {
		return &node{kind: nClass, items: []classItem{{fn: fn, neg: neg}}}, nil
	}
	return &node{kind: nLit, r: r, fold: f.i}, nil
}

func (p *parser) parseClass(f *flags) (*node, error) {
	p.pos++ // [
	n := &node{kind: nClass, fold: f.i}
	if p.peek() == '^' {
		n.negated = true
		p.pos++
	}
	first := true
	for p.more() {
		c := p.peek()
		if c == ']' && !first {
			p.pos++
			return n, nil
		}
		first = false
		var lo rune
		if c == '[' && p.pos+1 < len(p.src) && p.src[p.pos+1] == ':' {
			// POSIX class
			end := strings.Index(string(p.src[p.pos:]), ":]")
			if end > 0 {
				name := string(p.src[p.pos+2 : p.pos+end])
				p.pos += end + 2
				var fn func(rune) bool
				switch name {
				case "alpha":
					fn = unicode.IsLetter
				case "digit":
					fn = func(r rune) bool { return r >= '0' && r <= '9' }
				case "alnum":
					fn = func(r rune) bool { return unicode.IsLetter(r) || unicode.IsDigit(r) }
				case "space":
					fn = unicode.IsSpace
				case "upper":
					fn = unicode.IsUpper
				case "lower":
					fn = unicode.IsLower
				case "punct":
					fn = unicode.IsPunct
				case "xdigit":
					fn = func(r rune) bool { return strings.ContainsRune("0123456789abcdefABCDEF", r) }
				default:
					fn = func(rune) bool { return false }
				}
				n.items = append(n.items, classItem{fn: fn})
				continue
			}
		}
		if c == '\\' {
			r, fn, neg, err := p.parseEscapeRune()
			if err != nil {
				return nil, err
			}
			if fn != nil {
				n.items = append(n.items, classItem{fn: fn, neg: neg})
				continue
			}
			if r == 'b' && p.src[p.pos-1] == 'b' {
				r = '\b'
			}
			lo = r
		} else {
			lo = c
			p.pos++
		}
		hi := lo
		if p.peek() == '-' && p.pos+1 < len(p.src) && p.src[p.pos+1] != ']' {
			p.pos++
			c2 := p.peek()
			if c2 == '\\' {
				r, fn, _, err := p.parseEscapeRune()
				if err != nil {
					return nil, err
				}
				if fn != nil {
					// not a range; add literal '-'
					n.items = append(n.items, classItem{lo: lo, hi: lo}, classItem{lo: '-', hi: '-'})
					continue
				}
				hi = r
			} else if c2 == '[' {
				// class subtraction - unsupported, treat literally
				hi = lo
				p.pos--
			} else {
				hi = c2
				p.pos++
			}
		}
		n.items = append(n.items, classItem{lo: lo, hi: hi})
	}
	return nil, fmt.Errorf("rx: missing ]")
}

// ---------------------------------------------------------------------------
// matching

type matcher struct {
	in    []rune
	start int
	caps  []int
	steps int
}

func (n *node) classMatch(r rune) bool {
	m := false
	for _, it := range n.items {
		if it.fn != nil {
			if it.fn(r) != it.neg {
				m = true
				break
			}
			continue
		}
		if r >= it.lo && r <= it.hi {
			m = true
			break
		}
		if n.fold {
			lr := unicode.ToLower(r)
			ur := unicode.ToUpper(r)
			if (lr >= it.lo && lr <= it.hi) || (ur >= it.lo && ur <= it.hi) {
				m = true
				break
			}
		}
	}
	return m != n.negated
}

func eqFold(a, b rune) bool {
	if a == b {
		return true
	}
	return unicode.ToLower(a) == unicode.ToLower(b) || unicode.ToUpper(a) == unicode.ToUpper(b)
}

func (m *matcher) isWordAt(i int) bool {
	return i >= 0 && i < len(m.in) && isWordRune(m.in[i])
}

// match tries node n at position i, calling k on success.
func (m *matcher) match(n *node, i int, k func(int) bool) bool {
	switch n.kind {
	case nEmpty:
		return k(i)
	case nLit:
		if i < len(m.in) && (m.in[i] == n.r || (n.fold && eqFold(m.in[i], n.r))) {
			return k(i + 1)
		}
		return false
	case nAny:
		if i < len(m.in) && (n.dotAll || m.in[i] != '\n') {
			return k(i + 1)
		}
		return false
	case nClass:
		if i < len(m.in) && n.classMatch(m.in[i]) {
			return k(i + 1)
		}
		return false
	case nConcat:
		return m.matchSeq(n.subs, 0, i, k)
	case nAlt:
		for _, s := range n.subs {
			if m.match(s, i, k) {
				return true
			}
		}
		return false
	case nGroup:
		g := n.group
		old0, old1 := m.caps[2*g], m.caps[2*g+1]
		if m.match(n.subs[0], i, func(j int) bool {
			s0, s1 := m.caps[2*g], m.caps[2*g+1]
			m.caps[2*g], m.caps[2*g+1] = i, j
			if k(j) {
				return true
			}
			m.caps[2*g], m.caps[2*g+1] = s0, s1
			return false
		}) {
			return true
		}
		m.caps[2*g], m.caps[2*g+1] = old0, old1
		return false
	case nNonCap:
		return m.match(n.subs[0], i, k)
	case nLookahead:
		saved := append([]int(nil), m.caps...)
		if m.match(n.subs[0], i, func(int) bool { return true }) {
			return k(i)
		}
		copy(m.caps, saved)
		return false
	case nNegLookahead:
		saved := append([]int(nil), m.caps...)
		ok := m.match(n.subs[0], i, func(int) bool { return true })
		copy(m.caps, saved)
		if ok {
			return false
		}
		return k(i)
	case nLookbehind, nNegLookbehind:
		found := false
		saved := append([]int(nil), m.caps...)
		for st := i; st >= 0; st-- {
			if m.match(n.subs[0], st, func(j int) bool { return j == i }) {
				found = true
				break
			}
		}
		if n.kind == nNegLookbehind {
			copy(m.caps, saved)
			if found {
				return false
			}
			return k(i)
		}
		if !found {
			copy(m.caps, saved)
			return false
		}
		return k(i)
	case nBol:
		if i == 0 || (n.multi && m.in[i-1] == '\n') {
			return k(i)
		}
		return false
	case nEol:
		if i == len(m.in) || (n.multi && m.in[i] == '\n') || (!n.multi && i == len(m.in)-1 && m.in[i] == '\n') {
			return k(i)
		}
		return false
	case nStart:
		if i == 0 {
			return k(i)
		}
		return false
	case nG:
		if i == m.start {
			return k(i)
		}
		return false
	case nEnd:
		if i == len(m.in) {
			return k(i)
		}
		return false
	case nEndZ:
		if i == len(m.in) || (i == len(m.in)-1 && m.in[i] == '\n') {
			return k(i)
		}
		return false
	case nWordB:
		if m.isWordAt(i-1) != m.isWordAt(i) {
			return k(i)
		}
		return false
	case nNWordB:
		if m.isWordAt(i-1) == m.isWordAt(i) {
			return k(i)
		}
		return false
	case nBackref:
		g := n.group
		if 2*g+1 >= len(m.caps) || m.caps[2*g] < 0 {
			// unset group: fails (regexp2 semantics)
			return false
		}
		sub := m.in[m.caps[2*g]:m.caps[2*g+1]]
		if i+len(sub) > len(m.in) {
			return false
		}
		for j, r := range sub {
			c := m.in[i+j]
			if c != r && !(n.fold && eqFold(c, r)) {
				return false
			}
		}
		return k(i + len(sub))
	case nRepeat:
		return m.matchRepeat(n, i, 0, -1, k)
	}
	return false
}

func (m *matcher) matchSeq(subs []*node, idx, i int, k func(int) bool) bool {
	if idx == len(subs) {
		return k(i)
	}
	return m.match(subs[idx], i, func(j int) bool { return m.matchSeq(subs, idx+1, j, k) })
}

func (m *matcher) matchRepeat(n *node, i, count, lastPos int, k func(int) bool) bool {
	sub := n.subs[0]
	canMore := n.max == -1 || count < n.max
	if count >= n.min && lastPos == i && count > 0 {
		// zero-width iteration: stop looping
		return k(i)
	}
	if n.lazy {
		if count >= n.min && k(i) {
			return true
		}
		if canMore {
			return m.match(sub, i, func(j int) bool {
				if j == i && count >= n.min {
					return false
				}
				return m.matchRepeat(n, j, count+1, i, k)
			})
		}
		return false
	}
	if canMore {
		if m.match(sub, i, func(j int) bool {
			if j == i && count >= n.min {
				return false
			}
			return m.matchRepeat(n, j, count+1, i, k)
		}) {
			return true
		}
	}
	if count >= n.min {
		return k(i)
	}
	return false
}

// MatchAt attempts an anchored match at pos. It returns the capture groups
// (group 0 is the whole match) or nil.
func (re *Regexp) MatchAt(in []rune, pos int) []string {
	m := &matcher{in: in, start: pos, caps: make([]int, 2*(re.ngroups+1))}
	for i := range m.caps {
		m.caps[i] = -1
	}
	end := -1
	if !m.match(re.root, pos, func(j int) bool { end = j; return true }) {
		return nil
	}
	out := make([]string, re.ngroups+1)
	out[0] = string(in[pos:end])
	for g := 1; g <= re.ngroups; g++ {
		if m.caps[2*g] >= 0 {
			out[g] = string(in[m.caps[2*g]:m.caps[2*g+1]])
		}
	}
	return out
}

// FindAt searches for the first match starting at or after pos.
func (re *Regexp) FindAt(in []rune, pos int) (int, []string) {
	for st := pos; st <= len(in); st++ {
		if g := re.MatchAt(in, st); g != nil {
			return st, g
		}
	}
	return -1, nil
}

// MatchString reports whether s contains a match.
func (re *Regexp) MatchString(s string) bool {
	st, _ := re.FindAt([]rune(s), 0)
	return st >= 0
}

// NumGroups returns the number of capture groups.
func (re *Regexp) NumGroups() int { return re.ngroups }

// GroupNames returns the named group indices.
func (re *Regexp) GroupNames() map[string]int { return re.names }
