}

// UsingSelf lexes the match with the same lexer starting at state.
func UsingSelf(state string) Emitter { return usingSelf{state} }

type usingLexer struct{ name string }

func (u usingLexer) Emit(groups []string, st *lexState) []Token {
	l := Get(u.name)
	if l == nil {
		return []Token{{Type: "Text", Value: groups[0]}}
	}
	return l.tokenise(groups[0], "root", true)
}

// Using lexes the match with another lexer.
func Using(name string) Emitter { return usingLexer{name} }

// Mutator changes the state stack.
type Mutator interface {
	Mutate(st *lexState)
}

type push []string

func (p push) Mutate(st *lexState) {
	if len(p) == 0 {
		st.stack = append(st.stack, st.stack[len(st.stack)-1])
		return
	}
	for _, s := range p {
		if s == "#pop" {
			if len(st.stack) > 0 {
				st.stack = st.stack[:len(st.stack)-1]
			}
		} else {
			st.stack = append(st.stack, s)
		}
	}
}

// Push pushes states (or re-pushes the current state when empty).
func Push(states ...string) Mutator { return push(states) }

type pop int

func (p pop) Mutate(st *lexState) {
	n := int(p)
	if len(st.stack) <= n {
		st.stack = st.stack[:0]
		if len(st.stack) == 0 {
			st.stack = []string{}
		}
		return
	}
	st.stack = st.stack[:len(st.stack)-n]
}

// Pop pops n states.
func Pop(n int) Mutator { return pop(n) }

type mutators []Mutator

func (m mutators) Mutate(st *lexState) {
	for _, x := range m {
		x.Mutate(st)
	}
}

// Mutators combines mutators.
func Mutators(m ...Mutator) Mutator { return mutators(m) }

// Rule is a single lexer rule.
type Rule struct {
	Pattern string
	Type    Emitter
	Mutator Mutator
	include string
	re      *rx.Regexp
}

// Include includes the rules of another state.
func Include(state string) Rule { return Rule{include: state} }

// Default is a rule that matches nothing and applies mutators.
func Default(m ...Mutator) Rule { return Rule{Pattern: "", Mutator: Mutators(m...)} }

// Rules maps state names to rules.
type Rules map[string][]Rule

// Config describes a lexer.
type Config struct {
	Name            string
	Aliases         []string
	Filenames       []string
	CaseInsensitive bool
	DotAll          bool
	NotMultiline    bool
	EnsureNL        bool
	Priority        float32
}

// Lexer is a compiled regex lexer.
type Lexer struct {
	Config   Config
	rules    map[string][]*Rule
	rulesFn  func() Rules
	analyse  func(text string) float32
	compiled bool
}

func (l *Lexer) compile() {
	if l.compiled {
		return
	}
	l.compiled = true
	raw := l.rulesFn()
	flags := ""
	if !l.Config.NotMultiline {
		flags += "m"
	}
	if l.Config.CaseInsensitive {
		flags += "i"
	}
	if l.Config.DotAll {
		flags += "s"
	}
	l.rules = map[string][]*Rule{}
	var expand func(state string, seen map[string]bool) []*Rule
	expand = func(state string, seen map[string]bool) []*Rule {
		var out []*Rule
		for i := range raw[state] {
			r := raw[state][i]
			if r.include != "" {
				if seen[r.include] {
					continue
				}
				seen[r.include] = true
				out = append(out, expand(r.include, seen)...)
				delete(seen, r.include)
				continue
			}
			pat := "(?:" + r.Pattern + ")"
			if flags != "" {
				pat = "(?" + flags + ")" + pat
			}
			rr := r
			rr.re = rx.MustCompile(pat)
			out = append(out, &rr)
		}
		return out
	}
	for state := range raw {
		l.rules[state] = expand(state, map[string]bool{state: true})
	}
}

type lexState struct {
	lexer *Lexer
	text  []rune
	pos   int
	stack []string
}

func (l *Lexer) tokenise(text string, state string, nested bool) []Token {
	l.compile()
	newlineAdded := false
	if !nested && l.Config.EnsureNL && !strings.HasSuffix(text, "\n") {
		text += "\n"
		newlineAdded = true
	}
	st := &lexState{lexer: l, text: []rune(text), stack: []string{state}}
	end := len(st.text)
	if newlineAdded {
		end--
	}
	var out []Token
	for st.pos < end && len(st.stack) > 0 {
		cur := st.stack[len(st.stack)-1]
		rules := l.rules[cur]
		var matched *Rule
		var groups []string
		for _, r := range rules {
			if g := r.re.MatchAt(st.text, st.pos); g != nil {
				matched = r
				groups = g
				break
			}
		}
		if matched == nil {
			if st.text[st.pos] == '\n' && cur != state {
				st.stack = []string{state}
				continue
			}
			st.pos++
			out = append(out, Token{Type: "Error", Value: string(st.text[st.pos-1 : st.pos])})
			continue
		}
		st.pos += len([]rune(groups[0]))
		if matched.Mutator != nil {
			matched.Mutator.Mutate(st)
		}
		if matched.Type != nil {
			out = append(out, matched.Type.Emit(groups, st)...)
		}
	}
	if st.pos != len(st.text) && len(st.stack) == 0 {
		out = append(out, Token{Type: "Error", Value: string(st.text[st.pos:])})
	}
	return out
}

// Tokenise lexes text into coalesced tokens.
func (l *Lexer) Tokenise(text string) []Token {
	text = ensureLF(text)
	toks := l.tokenise(text, "root", false)
	return coalesce(toks)
}

func ensureLF(text string) string {
	if !strings.Contains(text, "\r") {
		return text
	}
	var b strings.Builder
	for i := 0; i < len(text); i++ {
		c := text[i]
		if c == '\r' {
			if i+1 < len(text) && text[i+1] == '\n' {
				continue
			}
			b.WriteByte('\n')
			continue
		}
		b.WriteByte(c)
	}
	return b.String()
}

func coalesce(toks []Token) []Token {
	var out []Token
	for _, t := range toks {
		if t.Value == "" {
			continue
		}
		if len(out) > 0 && out[len(out)-1].Type == t.Type && len(out[len(out)-1].Value) < 8192 {
			out[len(out)-1].Value += t.Value
			continue
		}
		out = append(out, t)
	}
	return out
}

var registry []*Lexer

// Register adds a lexer to the registry.
func Register(cfg Config, rules func() Rules, analyse func(string) float32) *Lexer {
	l := &Lexer{Config: cfg, rulesFn: rules, analyse: analyse}
	registry = append(registry, l)
	return l
}

func matchGlob(pattern, name string) bool {
	ok, err := pathMatch(pattern, name)
	return err == nil && ok
}

// Get finds a lexer by name, alias or filename extension.
func Get(name string) *Lexer {
	for _, l := range registry {
		if l.Config.Name == name {
			return l
		}
	}
	for _, l := range registry {
		for _, a := range l.Config.Aliases {
			if a == name {
				return l
			}
		}
	}
	lname := strings.ToLower(name)
	for _, l := range registry {
		if strings.ToLower(l.Config.Name) == lname {
			return l
		}
	}
	for _, l := range registry {
		for _, a := range l.Config.Aliases {
			if a == lname {
				return l
			}
		}
	}
	var cands []*Lexer
	if l := match("filename." + name); l != nil {
		cands = append(cands, l)
	}
	if l := match(name); l != nil {
		cands = append(cands, l)
	}
	if len(cands) == 0 {
		return nil
	}
	best := cands[0]
	for _, c := range cands[1:] {
		if c.Config.Priority > best.Config.Priority {
			best = c
		}
	}
	return best
}

func match(filename string) *Lexer {
	base := filename
	if i := strings.LastIndexAny(base, "/\\"); i >= 0 {
		base = base[i+1:]
	}
	var cands []*Lexer
	for _, l := range registry {
		for _, g := range l.Config.Filenames {
			if matchGlob(g, base) {
				cands = append(cands, l)
				break
			}
		}
	}
	if len(cands) == 0 {
		return nil
	}
	best := cands[0]
	for _, c := range cands[1:] {
		if c.Config.Priority > best.Config.Priority {
			best = c
		}
	}
	return best
}

// Analyse picks a lexer based on the content of text.
func Analyse(text string) *Lexer {
	var best *Lexer
	var bestScore float32
	for _, l := range registry {
		if l.analyse == nil {
			continue
		}
		score := l.analyse(text)
		if score > bestScore {
			bestScore = score
			best = l
		}
	}
	return best
}
