func (l *Lexer) tokenise(text string, state string, nested bool) []Token {
	l.compile()
	newlineAdded := false
	if !nested && l.Config.EnsureNL && !strings.HasSuffix(text, "\n") {
		text += "\n"
		newlineAdded = true
	}
	st := &lexState{lexer: l, text: []rune(text), stack: []string{state}}
	end := len(st.text)
	if newlineAdded {
		end--
	}
	var out []Token
	for st.pos < end && len(st.stack) > 0 {
		cur := st.stack[len(st.stack)-1]
		rules := l.rules[cur]
		var matched *Rule
		var groups []string
		for _, r := range rules {
			if g := r.re.MatchAt(st.text, st.pos); g != nil {
				matched = r
				groups = g
				break
			}
		}
		if matched == nil {
			if st.text[st.pos] == '\n' && cur != state {
				st.stack = []string{state}
				continue
			}
			st.pos++
			out = append(out, Token{Type: "Error", Value: string(st.text[st.pos-1 : st.pos])})
			continue
		}
		st.pos += len([]rune(groups[0]))
		if matched.Mutator != nil {
			matched.Mutator.Mutate(st)
		}
		if matched.Type != nil {
			out = append(out, matched.Type.Emit(groups, st)...)
		}
	}
	if st.pos != len(st.text) && len(st.stack) == 0 {
		out = append(out, Token{Type: "Error", Value: string(st.text[st.pos:])})
	}
	return out
}

// Tokenise lexes text into coalesced tokens.
func (l *Lexer) Tokenise(text string) []Token {
	text = ensureLF(text)
	toks := l.tokenise(text, "root", false)
	return coalesce(toks)
}

func ensureLF(text string) string {
	if !strings.Contains(text, "\r") {
		return text
	}
	var b strings.Builder
	for i := 0; i < len(text); i++ {
		c := text[i]
		if c == '\r' {
			if i+1 < len(text) && text[i+1] == '\n' {
				continue
			}
			b.WriteByte('\n')
			continue
		}
		b.WriteByte(c)
	}
	return b.String()
}

func coalesce(toks []Token) []Token {
	var out []Token
	for _, t := range toks {
		if t.Value == "" {
			continue
		}
		if len(out) > 0 && out[len(out)-1].Type == t.Type && len(out[len(out)-1].Value) < 8192 {
			out[len(out)-1].Value += t.Value
			continue
		}
		out = append(out, t)
	}
	return out
}

var registry []*Lexer

// Register adds a lexer to the registry.
func Register(cfg Config, rules func() Rules, analyse func(string) float32) *Lexer {
	l := &Lexer{Config: cfg, rulesFn: rules, analyse: analyse}
	registry = append(registry, l)
	return l
}

func matchGlob(pattern, name string) bool {
	ok, err := pathMatch(pattern, name)
	return err == nil && ok
}

// Get finds a lexer by name, alias or filename extension.
func Get(name string) *Lexer {
	for _, l := range registry {
		if l.Config.Name == name {
			return l
		}
	}
	for _, l := range registry {
		for _, a := range l.Config.Aliases {
			if a == name {
				return l
			}
		}
	}
	lname := strings.ToLower(name)
	for _, l := range registry {
		if strings.ToLower(l.Config.Name) == lname {
			return l
		}
	}
	for _, l := range registry {
		for _, a := range l.Config.Aliases {
			if a == lname {
				return l
			}
		}
	}
	var cands []*Lexer
	if l := match("filename." + name); l != nil {
		cands = append(cands, l)
	}
	if l := match(name); l != nil {
		cands = append(cands, l)
	}
	if len(cands) == 0 {
		return nil
	}
	best := cands[0]
	for _, c := range cands[1:] {
		if c.Config.Priority > best.Config.Priority {
			best = c
		}
	}
	return best
}

func match(filename string) *Lexer {
	base := filename
	if i := strings.LastIndexAny(base, "/\\"); i >= 0 {
		base = base[i+1:]
	}
	var cands []*Lexer
	for _, l := range registry {
		for _, g := range l.Config.Filenames {
			if matchGlob(g, base) {
				cands = append(cands, l)
				break
			}
		}
	}
	if len(cands) == 0 {
		return nil
	}
	best := cands[0]
	for _, c := range cands[1:] {
		if c.Config.Priority > best.Config.Priority {
			best = c
		}
	}
	return best
}

// Analyse picks a lexer based on the content of text.
func Analyse(text string) *Lexer {
	var best *Lexer
	var bestScore float32
	for _, l := range registry {
		if l.analyse == nil {
			continue
		}
		score := l.analyse(text)
		if score > bestScore {
			bestScore = score
			best = l
		}
	}
	return best
}
