package hl

type style struct {
	entries map[string][3]string
}

func lookupStyle(name string) style {
	if s, ok := styleData[name]; ok {
		return style{s}
	}
	return style{styleData["swapoff"]}
}

// parents lists fallback token types for types without observed data.
var parents = map[string]string{}

func parentType(t string) string {
	if p, ok := parents[t]; ok {
		return p
	}
	// strip trailing CamelCase component
	for i := len(t) - 1; i > 0; i-- {
		if t[i] >= 'A' && t[i] <= 'Z' {
			return t[:i]
		}
	}
	return ""
}

func (s style) escape(t string, fidx int) string {
	for cur := t; cur != ""; cur = parentType(cur) {
		if e, ok := s.entries[cur]; ok {
			return e[fidx]
		}
	}
	if e, ok := s.entries["Text"]; ok {
		return e[fidx]
	}
	return ""
}
