	for _, combo := range [][2]string{{"rfstringescape", "tdqf"}, {"rfstringescape", "tsqf"}, {"rfstringescape", "dqf"}, {"rfstringescape", "sqf"},
		{"fstringescape", "tdqf"}, {"fstringescape", "tsqf"}, {"fstringescape", "dqf"}, {"fstringescape", "sqf"},
		{"stringescape", "tdqs"}, {"stringescape", "tsqs"}, {"stringescape", "dqs"}, {"stringescape", "sqs"},
		{"bytesescape", "tdqs"}, {"bytesescape", "tsqs"}, {"bytesescape", "dqs"}, {"bytesescape", "sqs"}} {
		r[combo[0]+"+"+combo[1]] = []Rule{Include(combo[0]), Include(combo[1])}
	}
	return r
