type usingByGroup struct {
	sublexerGroup, codeGroup int
	emitters                 []Emitter
}

func (u usingByGroup) Emit(groups []string, st *lexState) []Token {
	var out []Token
	l := Get(groups[u.sublexerGroup])
	for i := 1; i < len(groups) && i-1 < len(u.emitters); i++ {
		if i == u.codeGroup && l != nil {
			out = append(out, l.tokenise(groups[i], "root", true)...)
			continue
		}
		if u.emitters[i-1] != nil {
			out = append(out, u.emitters[i-1].Emit([]string{groups[i]}, st)...)
		}
	}
	return out
}

// UsingByGroup lexes one group with a lexer named by another group.
